window.GNN_NOTES=window.GNN_NOTES||{};window.GNN_NOTES["1"]={"week":"1","title":"1주차. 그래프 입문","units":[{"id":"w1-1","title":"점과 선의 세계: 그래프 적기, 저장하기, 크기 재기","goal":"그래프를 인접행렬과 인접리스트로 적고, 지름과 엣지 밀도를 계산할 수 있어요","terms":[{"en":"Node","ko":"노드","say":"개체를 나타내는 점"},{"en":"Edge","ko":"엣지","say":"두 노드를 잇는 관계 선"},{"en":"Degree","ko":"차수","say":"노드에 붙은 엣지 수, 친구 수"},{"en":"Adjacency matrix","ko":"인접행렬","say":"연결 있으면 1, 없으면 0을 적은 표"},{"en":"Adjacency list","ko":"인접리스트","say":"노드마다 이웃 목록만 적은 수첩"},{"en":"Sparse graph","ko":"희소 그래프","say":"가능한 엣지에 비해 실제 엣지가 아주 적은 그래프"},{"en":"Diameter","ko":"지름","say":"모든 쌍의 최단 거리 중 가장 큰 값"},{"en":"Edge density","ko":"엣지 밀도","say":"가능한 엣지 중 실제 엣지의 비율"},{"en":"Degree distribution","ko":"차수 분포","say":"차수가 k인 노드가 몇 개인지"},{"en":"Scale-free","ko":"스케일 프리","say":"소수 허브 노드에 연결이 몰린 성질"}],"slides":[{"kind":"title","big":"점과 선의 세계","sub":"그래프를 적고, 저장하고, 크기를 재요"},{"kind":"goal","items":["그래프가 **노드(Node)**와 **엣지(Edge)**로 된 데이터임을 말할 수 있어요","**인접행렬(Adjacency matrix)**과 **인접리스트(Adjacency list)**를 비교할 수 있어요","**지름(Diameter)**과 **엣지 밀도(Edge density)**를 계산할 수 있어요","**차수 분포(Degree distribution)**와 **스케일 프리(Scale-free)**를 설명할 수 있어요"]},{"kind":"analogy","head":"반 친구 관계도를 떠올려요","scene":"반 친구 이름을 동그라미로 쓰고, 친한 사이끼리 선을 그어 봐요. 그 그림이 바로 그래프예요.","map":[["친구 한 명","**노드(Node)**"],["친한 사이를 잇는 선","**엣지(Edge)**"],["내 친구 수","**차수(Degree)**"],["관계도 전체","그래프 $G=(V,E)$"]]},{"kind":"points","head":"왜 그래프가 필요할까요","items":["표는 정형 데이터, 이미지는 격자, 텍스트는 한 줄이에요","교통망, SNS, 분자는 이런 일정한 틀이 없어요","그래서 개체는 **노드(Node)**, 관계는 **엣지(Edge)**로 적어요","화살표가 있으면 방향 그래프, 세기가 있으면 가중 그래프예요","교수님: 그래프 데이터용 신경망이 이번 학기의 GNN이에요"]},{"kind":"figure","head":"같은 그래프, 두 가지 저장법","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><line class=\"e\" x1=\"80\" y1=\"63\" x2=\"158\" y2=\"63\"/><polygon class=\"arrow\" points=\"170,63 158,69 158,57\"/><line class=\"e\" x1=\"170\" y1=\"77\" x2=\"92\" y2=\"77\"/><polygon class=\"arrow\" points=\"80,77 92,71 92,83\"/><line class=\"e\" x1=\"190\" y1=\"180\" x2=\"190\" y2=\"102\"/><polygon class=\"arrow\" points=\"190,90 196,102 184,102\"/><line class=\"e\" x1=\"170\" y1=\"200\" x2=\"92\" y2=\"200\"/><polygon class=\"arrow\" points=\"80,200 92,194 92,206\"/><circle class=\"n\" cx=\"60\" cy=\"70\" r=\"20\"/><text class=\"tl\" x=\"60\" y=\"76\" font-size=\"16\" text-anchor=\"middle\">A<\/text><circle class=\"n\" cx=\"190\" cy=\"70\" r=\"20\"/><text class=\"tl\" x=\"190\" y=\"76\" font-size=\"16\" text-anchor=\"middle\">B<\/text><circle class=\"n2\" cx=\"190\" cy=\"200\" r=\"20\"/><text class=\"tl\" x=\"190\" y=\"206\" font-size=\"16\" text-anchor=\"middle\">C<\/text><circle class=\"n\" cx=\"60\" cy=\"200\" r=\"20\"/><text class=\"tl\" x=\"60\" y=\"206\" font-size=\"16\" text-anchor=\"middle\">D<\/text><text class=\"tb b1\" x=\"250\" y=\"40\" font-size=\"16\" text-anchor=\"start\">행렬 16칸<\/text><text class=\"t b1\" x=\"250\" y=\"80\" font-size=\"16\" text-anchor=\"start\">A: 0 1 0 0<\/text><text class=\"t b1\" x=\"250\" y=\"110\" font-size=\"16\" text-anchor=\"start\">B: 1 0 0 0<\/text><text class=\"t b1\" x=\"250\" y=\"140\" font-size=\"16\" text-anchor=\"start\">C: 0 1 0 1<\/text><text class=\"t b1\" x=\"250\" y=\"170\" font-size=\"16\" text-anchor=\"start\">D: 0 0 0 0<\/text><text class=\"tb b2\" x=\"370\" y=\"40\" font-size=\"16\" text-anchor=\"start\">리스트 8칸<\/text><text class=\"t b2\" x=\"370\" y=\"80\" font-size=\"16\" text-anchor=\"start\">A: B<\/text><text class=\"t b2\" x=\"370\" y=\"110\" font-size=\"16\" text-anchor=\"start\">B: A<\/text><text class=\"t b2\" x=\"370\" y=\"140\" font-size=\"16\" text-anchor=\"start\">C: B, D<\/text><text class=\"t b2\" x=\"370\" y=\"170\" font-size=\"16\" text-anchor=\"start\">D: 없음<\/text><text class=\"tb b3\" x=\"240\" y=\"255\" font-size=\"16\" text-anchor=\"middle\">0이 대부분이면 리스트가 유리해요<\/text><\/svg>","caption":"엣지 A→B, B→A, C→B, C→D를 **인접행렬(Adjacency matrix)**과 **인접리스트(Adjacency list)**로 적었어요","builds":3},{"kind":"formula","head":"인접행렬과 차수","tex":"A_{uv}=\\begin{cases}1 & (u,v)\\in E\\\\ 0 & \\text{otherwise}\\end{cases},\\qquad d(v_i)=\\sum_j A_{ij}","parts":[{"sym":"A_{uv}","say":"행 $u$(출발), 열 $v$(도착) 칸의 값"},{"sym":"(u,v)\\in E","say":"u에서 v로 가는 **엣지(Edge)**가 있다"},{"sym":"d(v_i)","say":"노드 $v_i$의 **차수(Degree)**, 친구 수"},{"sym":"\\sum_j A_{ij}","say":"i번째 행을 가로로 다 더하기"}],"whole":"**인접행렬(Adjacency matrix)** 칸에 연결이면 1을 적고, 한 행을 더하면 차수가 나와요"},{"kind":"compare","head":"행렬과 리스트, 시간과 공간","cols":["작업","**인접행렬(Adjacency matrix)**","**인접리스트(Adjacency list)**"],"rows":[["엣지가 있나 확인","$O(1)$","$O(d)$"],["나가는 엣지 꺼내기","$O(|V|)$","$O(d)$"],["들어오는 엣지 찾기","$O(|V|)$","$O(|E|)$"],["공간","$O(|V|^2)$","$O(|V|+|E|)$"],["잘 맞는 그래프","밀집(dense)","**희소 그래프(Sparse graph)**"]]},{"kind":"check","q":"SNS처럼 **희소 그래프(Sparse graph)**를 저장할 때 가장 알맞은 것은?","choices":["인접행렬, 공간 $O(|V|^2)$","인접리스트, 공간 $O(|V|+|E|)$","모든 칸을 0으로 채운 표"],"a":1,"why":"0을 적지 않는 **인접리스트(Adjacency list)**가 공간을 크게 아껴요. PyTorch Geometric도 엣지 목록으로 저장해요"},{"kind":"analogy","head":"소문이 반 전체에 퍼지려면","scene":"소문은 친구에서 친구로 한 걸음씩 퍼져요. 반 끝에서 끝까지 가장 오래 걸리는 걸음 수를 세어 봐요.","map":[["소문이 한 번 건너가기","1홉(hop)"],["끝에서 끝까지 최대 걸음 수","**지름(Diameter)**"],["반이 얼마나 촘촘히 친한지","**엣지 밀도(Edge density)**"]]},{"kind":"formula","head":"지름과 엣지 밀도","tex":"D=\\max_{u,v\\in V} d(u,v),\\qquad \\text{density}=\\frac{|E|}{n(n-1)/2}","parts":[{"sym":"d(u,v)","say":"u에서 v까지 최단 경로의 엣지 수"},{"sym":"\\max_{u,v}","say":"모든 노드 쌍 중 가장 큰 값"},{"sym":"|E|","say":"실제 엣지 수"},{"sym":"n(n-1)/2","say":"무방향 그래프에서 가능한 엣지 수"}],"whole":"**지름(Diameter)**은 최단 거리들의 최댓값, **엣지 밀도(Edge density)**는 실제 엣지 비율이에요"},{"kind":"figure","head":"가장 먼 두 노드 찾기","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><line class=\"e\" x1=\"70\" y1=\"70\" x2=\"190\" y2=\"70\"/><line class=\"e\" x1=\"190\" y1=\"70\" x2=\"310\" y2=\"70\"/><line class=\"e\" x1=\"70\" y1=\"180\" x2=\"190\" y2=\"180\"/><line class=\"e\" x1=\"190\" y1=\"180\" x2=\"310\" y2=\"180\"/><line class=\"e\" x1=\"70\" y1=\"70\" x2=\"70\" y2=\"180\"/><line class=\"e\" x1=\"310\" y1=\"70\" x2=\"310\" y2=\"180\"/><line class=\"e\" x1=\"70\" y1=\"180\" x2=\"310\" y2=\"70\"/><line class=\"e\" x1=\"310\" y1=\"180\" x2=\"420\" y2=\"240\"/><line class=\"e2 b1\" x1=\"420\" y1=\"240\" x2=\"310\" y2=\"180\"/><line class=\"e2 b2\" x1=\"310\" y1=\"180\" x2=\"310\" y2=\"70\"/><line class=\"e2 b3\" x1=\"310\" y1=\"70\" x2=\"190\" y2=\"70\"/><line class=\"e2 b4\" x1=\"190\" y1=\"70\" x2=\"70\" y2=\"70\"/><circle class=\"n2\" cx=\"70\" cy=\"70\" r=\"20\"/><text class=\"tl\" x=\"70\" y=\"76\" font-size=\"16\" text-anchor=\"middle\">2<\/text><circle class=\"n\" cx=\"190\" cy=\"70\" r=\"20\"/><text class=\"tl\" x=\"190\" y=\"76\" font-size=\"16\" text-anchor=\"middle\">4<\/text><circle class=\"n\" cx=\"310\" cy=\"70\" r=\"20\"/><text class=\"tl\" x=\"310\" y=\"76\" font-size=\"16\" text-anchor=\"middle\">6<\/text><circle class=\"n\" cx=\"70\" cy=\"180\" r=\"20\"/><text class=\"tl\" x=\"70\" y=\"186\" font-size=\"16\" text-anchor=\"middle\">1<\/text><circle class=\"n\" cx=\"190\" cy=\"180\" r=\"20\"/><text class=\"tl\" x=\"190\" y=\"186\" font-size=\"16\" text-anchor=\"middle\">3<\/text><circle class=\"n\" cx=\"310\" cy=\"180\" r=\"20\"/><text class=\"tl\" x=\"310\" y=\"186\" font-size=\"16\" text-anchor=\"middle\">5<\/text><circle class=\"n2\" cx=\"420\" cy=\"240\" r=\"20\"/><text class=\"tl\" x=\"420\" y=\"246\" font-size=\"16\" text-anchor=\"middle\">7<\/text><text class=\"tb b4\" x=\"420\" y=\"60\" font-size=\"16\" text-anchor=\"middle\">D = 4<\/text><text class=\"t b4\" x=\"420\" y=\"90\" font-size=\"16\" text-anchor=\"middle\">7-5-6-4-2<\/text><\/svg>","caption":"L1 p.19 그래프. 노드 7에서 2까지 최단 경로가 4걸음이고, 이게 **지름(Diameter)**이에요","builds":4},{"kind":"steps","head":"직접 계산: 지름과 밀도","given":"엣지 8개: 2-4, 4-6, 1-3, 3-5, 2-1, 6-5, 1-6, 5-7 (노드 7개)","steps":["1단계. 노드 7에서 걸음 수: 5는 1, 3과 6은 2","2단계. 1과 4는 3걸음, 2는 4걸음","3단계. 다른 쌍은 모두 4 이하라서 **지름(Diameter)** $D=4$","4단계. 가능한 엣지 수 $7\\cdot6/2=21$","5단계. **엣지 밀도(Edge density)** $=8/21\\approx0.38$"],"answer":"$D=4$, 밀도 $8/21\\approx0.38$"},{"kind":"points","head":"차수 분포와 스케일 프리","items":["위 그래프의 **차수 분포(Degree distribution)**는 차수1 1개, 차수2 3개, 차수3 3개","검산: 차수 합 16 = 엣지 8개 × 2","교수님: 차수 분포는 구조를 반영하는 강력한 지표예요","SNS 같은 자연 그래프는 **스케일 프리(Scale-free)**, 허브에 연결이 몰려요","그래서 밀도가 거의 0인 **희소 그래프(Sparse graph)**가 돼요"]},{"kind":"english","head":"시험 문장: 저장 방식","en":"Real-world graphs are sparse, so adjacency lists with $O(|V|+|E|)$ space are preferred over an $O(|V|^2)$ adjacency matrix.","ko":"실제 그래프는 희소해서, 공간 $O(|V|^2)$인 인접행렬보다 $O(|V|+|E|)$인 인접리스트를 선호해요.","tip":"sparse(희소)와 adjacency list(인접리스트)가 채점 단어예요"},{"kind":"english","head":"시험 문장: 지름","en":"The diameter of a graph is the length of the longest shortest path between any pair of nodes.","ko":"그래프의 지름은 모든 노드 쌍의 최단 경로 중 가장 긴 것의 길이예요.","tip":"longest shortest path, '최단 중에 가장 긴'을 통째로 외워요"},{"kind":"check","q":"**Scale-free** 그래프의 뜻으로 맞는 것은?","choices":["모든 노드의 차수가 똑같은 그래프","소수 허브 노드에 연결이 몰린 그래프","엣지 밀도가 1인 그래프"],"a":1,"why":"**스케일 프리(Scale-free)**는 **차수 분포(Degree distribution)**가 크게 치우쳐 허브에 연결이 몰려요"},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**지름(Diameter)**은 가장 긴 경로가 아니라 최단 경로들 중 가장 긴 것. 비연결 그래프는 정의 안 돼요","**인접리스트(Adjacency list)**의 들어오는 엣지 찾기는 $O(|E|)$, 엣지 확인만은 행렬이 $O(1)$로 빨라요","슬라이드 p.16의 'also known as nodes'는 vertices의 오타예요"]},{"kind":"recap","items":["그래프 = **노드(Node)** 집합 + **엣지(Edge)** 집합, $G=(V,E)$","**인접행렬(Adjacency matrix)**은 $O(|V|^2)$, **인접리스트(Adjacency list)**는 $O(|V|+|E|)$","**지름(Diameter)**은 최단 거리의 최댓값, **엣지 밀도(Edge density)**는 $|E|/(n(n-1)/2)$","실제 그래프는 **스케일 프리(Scale-free)**이고 **희소 그래프(Sparse graph)**예요","오늘의 용어: Node(노드), Edge(엣지), Degree(차수), Adjacency matrix(인접행렬), Adjacency list(인접리스트), Sparse graph(희소 그래프), Diameter(지름), Edge density(엣지 밀도), Degree distribution(차수 분포), Scale-free(스케일 프리)"]}]},{"id":"w1-2","title":"누가 중요한 노드일까: 차수, 매개, 근접 중심성","goal":"차수, 매개, 근접 중심성을 계산하고 차수 중심성의 한계를 말할 수 있어요","terms":[{"en":"Centrality","ko":"중심성","say":"노드의 중요도를 숫자로 매긴 값"},{"en":"Degree centrality","ko":"차수 중심성","say":"친구 수로 매긴 중요도"},{"en":"Betweenness centrality","ko":"매개 중심성","say":"남들 사이 최단 경로에 얼마나 자주 끼어 있나"},{"en":"Closeness centrality","ko":"근접 중심성","say":"모든 노드까지 걸음 합이 얼마나 작은가"},{"en":"Shortest path","ko":"최단 경로","say":"두 노드 사이 걸음 수가 가장 적은 길"},{"en":"Bridge","ko":"다리","say":"서로 다른 무리를 잇는 노드"},{"en":"Over-squashing","ko":"과압축","say":"좁은 길목에 정보가 몰려 일부가 사라지는 GNN 문제"}],"slides":[{"kind":"title","big":"누가 중요한 노드일까","sub":"중심성 1편: 차수, 매개, 근접"},{"kind":"goal","items":["**중심성(Centrality)**이 무엇을 재는지 말할 수 있어요","**차수 중심성(Degree centrality)**의 한계를 설명할 수 있어요","**매개 중심성(Betweenness centrality)**을 계산할 수 있어요","**근접 중심성(Closeness centrality)**을 계산할 수 있어요"]},{"kind":"analogy","head":"반에서 중요한 친구는 누구?","scene":"친구가 제일 많은 아이, 두 무리 사이에서 소식을 전하는 아이, 누구에게든 금방 말이 닿는 아이. 셋 다 중요하지만 뜻이 달라요.","map":[["친구가 제일 많은 아이","**차수 중심성(Degree centrality)**"],["두 무리 사이 전달자","**매개 중심성(Betweenness centrality)**"],["누구에게나 금방 닿는 아이","**근접 중심성(Closeness centrality)**"]]},{"kind":"points","head":"교수님이 나눈 세 그룹","items":["앞에서 본 **차수(Degree)**와 **지름(Diameter)** 기억나죠? 오늘의 재료예요","그룹 1: **차수 중심성(Degree centrality)**, 바로 옆 1홉만 봐요","그룹 2: 매개와 근접, **최단 경로(Shortest path)** 기반이에요","그룹 3: 고유벡터, Katz, PageRank, 이웃 점수를 전파해요(다음 단원)","마이닝 2026 봄 중간은 **중심성(Centrality)** 문제만 35점이었어요"]},{"kind":"formula","head":"차수 중심성","tex":"C_D(v_i)=d(v_i)=\\sum_{j=1}^{n}A_{ij}","parts":[{"sym":"C_D(v_i)","say":"노드 $v_i$의 **차수 중심성(Degree centrality)**"},{"sym":"d(v_i)","say":"노드의 **차수(Degree)**, 친구 수"},{"sym":"A_{ij}","say":"인접행렬 칸, 연결이면 1"}],"whole":"인접행렬의 $i$번째 행을 더한 친구 수가 곧 중요도예요"},{"kind":"points","head":"차수 중심성의 한계","items":["순전히 국소적(local)이라 바로 옆만 봐요","무리를 잇는 **다리(Bridge)** 노드를 못 잡아요","친구가 3명뿐인 다리도 없어지면 동네가 끊어져요","이웃이 중요한 사람인지도 무시해요","그래프 전체 쏠림은 Freeman 중앙화: 별 그래프 1, 경로 그래프는 작아요"]},{"kind":"formula","head":"매개 중심성","tex":"c_v=\\sum_{s\\ne v\\ne t}\\frac{\\sigma_{st}(v)}{\\sigma_{st}}","parts":[{"sym":"\\sigma_{st}","say":"s와 t 사이 **최단 경로(Shortest path)**의 수"},{"sym":"\\sigma_{st}(v)","say":"그중 v를 지나는 경로의 수"},{"sym":"\\frac{\\sigma_{st}(v)}{\\sigma_{st}}","say":"v를 지나는 비율"},{"sym":"\\frac{(n-1)(n-2)}{2}","say":"정규화할 때 나누는 수(무방향)"}],"whole":"모든 쌍의 최단 경로 중 나를 지나는 비율을 다 더하면 **매개 중심성(Betweenness centrality)**이에요"},{"kind":"figure","head":"누가 길목에 서 있을까","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 300\"><line class=\"e\" x1=\"60\" y1=\"110\" x2=\"170\" y2=\"110\"/><line class=\"e\" x1=\"170\" y1=\"110\" x2=\"290\" y2=\"40\"/><line class=\"e\" x1=\"170\" y1=\"110\" x2=\"290\" y2=\"180\"/><line class=\"e\" x1=\"290\" y1=\"40\" x2=\"290\" y2=\"180\"/><line class=\"e\" x1=\"290\" y1=\"180\" x2=\"410\" y2=\"180\"/><circle class=\"n\" cx=\"60\" cy=\"110\" r=\"20\"/><text class=\"tl\" x=\"60\" y=\"116\" font-size=\"16\" text-anchor=\"middle\">A<\/text><circle class=\"n\" cx=\"170\" cy=\"110\" r=\"20\"/><text class=\"tl\" x=\"170\" y=\"116\" font-size=\"16\" text-anchor=\"middle\">C<\/text><circle class=\"n\" cx=\"290\" cy=\"40\" r=\"20\"/><text class=\"tl\" x=\"290\" y=\"46\" font-size=\"16\" text-anchor=\"middle\">B<\/text><circle class=\"n\" cx=\"290\" cy=\"180\" r=\"20\"/><text class=\"tl\" x=\"290\" y=\"186\" font-size=\"16\" text-anchor=\"middle\">D<\/text><circle class=\"n\" cx=\"410\" cy=\"180\" r=\"20\"/><text class=\"tl\" x=\"410\" y=\"186\" font-size=\"16\" text-anchor=\"middle\">E<\/text><circle class=\"n2 b1\" cx=\"170\" cy=\"110\" r=\"20\"/><text class=\"tl b1\" x=\"170\" y=\"116\" font-size=\"16\" text-anchor=\"middle\">C<\/text><circle class=\"n2 b2\" cx=\"290\" cy=\"180\" r=\"20\"/><text class=\"tl b2\" x=\"290\" y=\"186\" font-size=\"16\" text-anchor=\"middle\">D<\/text><text class=\"t b1\" x=\"20\" y=\"238\" font-size=\"15\" text-anchor=\"start\">C를 지나는 최단 경로: A-C-B, A-C-D, A-C-D-E<\/text><text class=\"t b2\" x=\"20\" y=\"263\" font-size=\"15\" text-anchor=\"start\">D를 지나는 최단 경로: A-C-D-E, B-D-E, C-D-E<\/text><text class=\"tb b3\" x=\"20\" y=\"288\" font-size=\"15\" text-anchor=\"start\">C, D 모두 3, 정규화하면 3/6 = 0.5<\/text><\/svg>","caption":"L1 p.29 그래프. C와 D의 **매개 중심성(Betweenness centrality)**이 3으로 가장 커요","builds":3},{"kind":"steps","head":"직접 계산: 일직선 그래프의 매개","given":"노드 7개가 $v_1$부터 $v_7$까지 일직선(p.30)","steps":["1단계. 정규화 분모 $(6\\cdot5)/2=15$","2단계. $v_2$를 지나는 쌍: $v_1$과 $v_3\\sim v_7$, 5쌍","3단계. $v_2$의 값 $5/15=0.33$","4단계. 가운데 $v_4$는 왼쪽 3명 × 오른쪽 3명 = 9쌍","5단계. $v_4$의 값 $9/15=0.60$"],"answer":"가운데일수록 **매개 중심성(Betweenness centrality)**이 커요"},{"kind":"formula","head":"근접 중심성","tex":"C_c(v)=\\frac{1}{\\sum_{u\\ne v}d(u,v)},\\qquad \\bar C(v)=\\frac{n-1}{\\sum_{u\\ne v}d(u,v)}","parts":[{"sym":"d(u,v)","say":"**최단 경로(Shortest path)** 길이, 걸음 수"},{"sym":"\\sum_{u\\ne v}","say":"나를 뺀 모든 노드까지 더하기"},{"sym":"n-1","say":"정규화용, 나를 뺀 노드 수"}],"whole":"모두까지 걸음 합이 작을수록 **근접 중심성(Closeness centrality)**이 커요"},{"kind":"steps","head":"직접 계산: 근접 중심성","given":"위 그림 그래프(A-C, B-C, B-D, C-D, D-E, p.32)","steps":["1단계. A에서 B, C, D, E까지 2, 1, 2, 3걸음","2단계. 합 8, $C_A=1/8$, 정규화 $4/8=0.5$","3단계. D에서 A, B, C, E까지 2, 1, 1, 1걸음","4단계. 합 5, $C_D=1/5$, 정규화 $4/5=0.8$"],"answer":"D가 모두에게 더 가까워 **근접 중심성(Closeness centrality)**이 더 커요"},{"kind":"points","head":"매개 중심성과 과압축","items":["**매개 중심성(Betweenness centrality)**이 높은 곳은 정보가 몰리는 길목이에요","GNN에서 노드 벡터 크기는 정해져 있어요","길목에 몰린 정보 일부가 날아가 버려요","교수님: 이게 **과압축(Over-squashing)**, 뒤 수업에서 다시 나와요"]},{"kind":"english","head":"시험 문장: 차수 중심성의 한계","en":"Degree centrality is purely local, so it cannot capture bridge nodes that connect different groups.","ko":"차수 중심성은 순전히 국소적이라 서로 다른 그룹을 잇는 다리 노드를 잡지 못해요.","tip":"local(국소적)과 bridge(다리) 두 단어가 채점 포인트예요"},{"kind":"english","head":"시험 문장: 매개 중심성","en":"Betweenness centrality counts how many shortest paths between other nodes pass through a node.","ko":"매개 중심성은 다른 노드들 사이 최단 경로 중 몇 개가 그 노드를 지나는지 세요."},{"kind":"check","q":"**Closeness centrality**는 무엇을 재나요?","choices":["친구 수","남들 사이 최단 경로에 끼어 있는 정도","모든 노드까지 걸음 합이 얼마나 작은지","중요한 이웃이 얼마나 많은지"],"a":2,"why":"**근접 중심성(Closeness centrality)**은 걸음 합의 역수라서 모두에게 가까울수록 커요"},{"kind":"check","q":"노드 5개 그래프에서 C를 지나는 최단 경로 쌍이 3개예요. 정규화한 **매개 중심성(Betweenness centrality)**은?","choices":["3/10","3/6 = 0.5","3/4","1/3"],"a":1,"why":"분모가 $(n-1)(n-2)/2=(4\\cdot3)/2=6$이라 $3/6=0.5$예요"},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["최단 경로가 여러 개면 나를 지나는 비율만큼만 더해요","근접 중심성은 거리 합이 작을수록 커요(역수). 정규화는 $(n-1)$을 곱해요","슬라이드 p.24 Freeman 식 분자의 (2-0)은 (2-2)의 오타예요"]},{"kind":"recap","items":["**중심성(Centrality)**은 노드 중요도를 숫자로 매긴 값이에요","**차수 중심성(Degree centrality)**은 친구 수, 국소적이라 **다리(Bridge)**를 놓쳐요","**매개 중심성(Betweenness centrality)**은 **최단 경로(Shortest path)** 위 길목 점수예요","**근접 중심성(Closeness centrality)**은 걸음 합의 역수, 길목은 **과압축(Over-squashing)**과 연결돼요","오늘의 용어: Centrality(중심성), Degree centrality(차수 중심성), Betweenness centrality(매개 중심성), Closeness centrality(근접 중심성), Shortest path(최단 경로), Bridge(다리), Over-squashing(과압축)"]}]},{"id":"w1-3","title":"점수를 퍼뜨리는 중심성: 고유벡터, Katz, PageRank","goal":"Katz와 PageRank를 계산하고, 점수 전파가 GNN의 씨앗인 이유를 말할 수 있어요","terms":[{"en":"Eigenvector centrality","ko":"고유벡터 중심성","say":"중요한 이웃에 둘러싸이면 중요"},{"en":"Katz centrality","ko":"카츠 중심성","say":"감쇠 인자와 기본 점수를 둔 점수 전파"},{"en":"PageRank","ko":"페이지랭크","say":"점수를 나가는 링크 수로 나눠 전달하는 점수 전파"},{"en":"Damping factor","ko":"감쇠 인자","say":"멀리서 온 정보의 가치를 줄이는 1보다 작은 수"},{"en":"Propagation","ko":"전파","say":"이웃에게서 점수를 끌어오기를 반복하는 것"},{"en":"Transition matrix","ko":"전이 행렬","say":"열 합이 1이 되게 나눈 행렬"}],"slides":[{"kind":"title","big":"점수를 퍼뜨리는 중심성","sub":"중심성 2편: 고유벡터, Katz, PageRank, 그리고 GNN"},{"kind":"goal","items":["**고유벡터 중심성(Eigenvector centrality)**의 생각을 말할 수 있어요","**카츠 중심성(Katz centrality)**을 계산할 수 있어요","**페이지랭크(PageRank)**를 반복 계산할 수 있어요","점수 **전파(Propagation)**가 왜 GNN의 씨앗인지 설명할 수 있어요"]},{"kind":"points","head":"앞 단원 다시 부르기","items":["**차수 중심성(Degree centrality)**은 친구 수만 셌어요","**매개 중심성(Betweenness centrality)**은 최단 경로 길목을 봤어요","오늘 그룹 3은 **전파(Propagation)**로 이웃 점수를 끌어와요","교수님: 이 뒤가 중요해요. GNN 작동 원리가 그대로 보여요"]},{"kind":"analogy","head":"추천서의 무게","scene":"유명한 교수님의 추천서는 무게가 커요. 그런데 그 교수님이 100명에게 써 줬다면 한 장의 무게는 줄어들죠.","map":[["유명한 사람이 써 준 추천","**고유벡터 중심성(Eigenvector centrality)**의 생각"],["100명에게 나눠 쓴 추천","**페이지랭크(PageRank)**: 나가는 링크 수로 나눔"],["건너 건너 들은 추천은 덜 믿음","**감쇠 인자(Damping factor)**"]]},{"kind":"formula","head":"고유벡터 중심성","tex":"c_v=\\frac{1}{\\lambda}\\sum_{u\\in N(v)}c_u\\iff\\lambda\\mathbf c=\\mathbf A\\mathbf c","parts":[{"sym":"c_v","say":"노드 v의 점수"},{"sym":"N(v)","say":"v의 이웃들"},{"sym":"\\frac{1}{\\lambda}","say":"점수가 끝없이 커지지 않게 나누는 수"},{"sym":"\\lambda\\mathbf c=\\mathbf A\\mathbf c","say":"점수 벡터가 인접행렬 $\\mathbf A$의 고유벡터"}],"whole":"이웃 점수를 더해 내 점수로 삼으면 **고유벡터 중심성(Eigenvector centrality)**이에요"},{"kind":"formula","head":"카츠 중심성","tex":"x_i=\\alpha\\sum_j A_{ij}x_j+\\beta","parts":[{"sym":"\\alpha","say":"**감쇠 인자(Damping factor)**, 1보다 작게"},{"sym":"\\sum_j A_{ij}x_j","say":"이웃 점수의 합"},{"sym":"\\beta","say":"모두에게 주는 기본 점수(편향)"},{"sym":"\\alpha=1/\\lambda_{max},\\ \\beta=0","say":"이러면 고유벡터 중심성과 같아요"}],"whole":"이웃 점수를 조금 줄여 더하고 기본 점수를 얹으면 **카츠 중심성(Katz centrality)**이에요"},{"kind":"steps","head":"직접 계산: Katz 한 번","given":"경로 1-2-3, $\\alpha=0.1$, $\\beta=1$, 처음 점수 모두 1","steps":["1단계. 노드 2의 이웃은 1과 3, 이웃 점수 합 $1+1=2$","2단계. $x_2=0.1\\times2+1=1.2$","3단계. 노드 1의 이웃은 2뿐, $x_1=0.1\\times1+1=1.1$","4단계. 노드 3도 같아서 $x_3=1.1$"],"answer":"$x=(1.1,\\ 1.2,\\ 1.1)$, 이웃 많은 2가 커요"},{"kind":"formula","head":"페이지랭크","tex":"R(u)=c\\sum_{v\\in B_u}\\frac{R(v)}{N_v}","parts":[{"sym":"B_u","say":"u를 가리키는 페이지들(백링크)"},{"sym":"N_v","say":"v에서 나가는 링크 수"},{"sym":"\\frac{R(v)}{N_v}","say":"v가 자기 점수를 똑같이 나눈 한 조각"},{"sym":"c","say":"합이 1이 되게 맞추는 수"}],"whole":"나를 가리키는 페이지 점수를 그쪽 링크 수로 나눠 받으면 **페이지랭크(PageRank)**예요"},{"kind":"figure","head":"PageRank 점수가 흐르는 길","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 300\"><path class=\"e\" d=\"M 88 72 C 60 10, 140 10, 112 72\" fill=\"none\"/><polygon class=\"arrow\" points=\"112,72 103,62 117,58\"/><text class=\"tm\" x=\"100\" y=\"22\" font-size=\"15\" text-anchor=\"middle\">1/2<\/text><line class=\"e\" x1=\"120\" y1=\"82\" x2=\"348\" y2=\"82\"/><polygon class=\"arrow\" points=\"360,82 348,88 348,76\"/><text class=\"tm\" x=\"240\" y=\"72\" font-size=\"15\" text-anchor=\"middle\">1/2<\/text><line class=\"e\" x1=\"360\" y1=\"98\" x2=\"132\" y2=\"98\"/><polygon class=\"arrow\" points=\"120,98 132,92 132,104\"/><text class=\"tm\" x=\"240\" y=\"122\" font-size=\"15\" text-anchor=\"middle\">1/2<\/text><line class=\"e\" x1=\"369\" y1=\"109\" x2=\"270\" y2=\"187\"/><polygon class=\"arrow\" points=\"261,194 266,182 274,191\"/><text class=\"tm\" x=\"335\" y=\"170\" font-size=\"15\" text-anchor=\"middle\">1/2<\/text><line class=\"e\" x1=\"251\" y1=\"181\" x2=\"350\" y2=\"103\"/><polygon class=\"arrow\" points=\"359,96 354,108 346,99\"/><text class=\"tm\" x=\"288\" y=\"125\" font-size=\"15\" text-anchor=\"middle\">1<\/text><circle class=\"n\" cx=\"100\" cy=\"90\" r=\"20\"/><text class=\"tl\" x=\"100\" y=\"96\" font-size=\"16\" text-anchor=\"middle\">Y<\/text><circle class=\"n\" cx=\"380\" cy=\"90\" r=\"20\"/><text class=\"tl\" x=\"380\" y=\"96\" font-size=\"16\" text-anchor=\"middle\">A<\/text><circle class=\"n\" cx=\"240\" cy=\"200\" r=\"20\"/><text class=\"tl\" x=\"240\" y=\"206\" font-size=\"16\" text-anchor=\"middle\">M<\/text><text class=\"t b1\" x=\"20\" y=\"245\" font-size=\"16\" text-anchor=\"start\">1회: Y 1/3, A 1/2, M 1/6<\/text><text class=\"t b2\" x=\"20\" y=\"268\" font-size=\"16\" text-anchor=\"start\">2회: Y 5/12, A 1/3, M 1/4<\/text><text class=\"tb b3\" x=\"20\" y=\"292\" font-size=\"16\" text-anchor=\"start\">수렴: Y 2/5, A 2/5, M 1/5<\/text><\/svg>","caption":"L1 p.37 Yahoo(Y), Amazon(A), Microsoft(M). 선 옆 숫자는 점수를 나눠 주는 비율이에요","builds":3},{"kind":"steps","head":"직접 계산: PageRank 반복","given":"Y는 자기와 A에 1/2씩, A는 Y와 M에 1/2씩, M은 A에 1","steps":["1단계. 열이 출발인 **전이 행렬(Transition matrix)**: Y행 (1/2, 1/2, 0), A행 (1/2, 0, 1), M행 (0, 1/2, 0)","2단계. 처음 점수 Y, A, M 모두 $1/3$","3단계. Y $=\\tfrac12\\cdot\\tfrac13+\\tfrac12\\cdot\\tfrac13=1/3$","4단계. A $=\\tfrac12\\cdot\\tfrac13+1\\cdot\\tfrac13=1/2$, M $=\\tfrac12\\cdot\\tfrac13=1/6$","5단계. 2회: Y $=5/12$, A $=1/3$, M $=1/4$","6단계. 계속하면 $(2/5,\\ 2/5,\\ 1/5)$로 수렴, 대입하면 그대로 나와요"],"answer":"**페이지랭크(PageRank)** 점수 Y $2/5$, A $2/5$, M $1/5$"},{"kind":"compare","head":"세 방법의 차이는 감쇠","cols":["측도","감쇠 방식","한 줄"],"rows":[["**고유벡터 중심성(Eigenvector centrality)**","$1/\\lambda$로 나눔","중요한 친구가 많음"],["**카츠 중심성(Katz centrality)**","$\\alpha<1$ + 기본 점수 $\\beta$","멀수록 가치가 낮음"],["**페이지랭크(PageRank)**","출발 노드의 나가는 링크 수로 나눔","인기 많은 친구의 표는 쪼개짐"],["GNN(2주차 GCN)","출발과 도착 노드 차수를 둘 다","양쪽 차수로 정규화"]]},{"kind":"figure","head":"점수 전파가 GNN이 되기까지","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><line class=\"e2 b1\" x1=\"41\" y1=\"69\" x2=\"71\" y2=\"109\"/><polygon class=\"arrow b1\" points=\"78,119 66,113 76,106\"/><line class=\"e2 b1\" x1=\"139\" y1=\"69\" x2=\"109\" y2=\"109\"/><polygon class=\"arrow b1\" points=\"102,119 104,106 114,113\"/><line class=\"e2 b1\" x1=\"41\" y1=\"201\" x2=\"71\" y2=\"161\"/><polygon class=\"arrow b1\" points=\"78,151 76,164 66,157\"/><line class=\"e2 b1\" x1=\"139\" y1=\"201\" x2=\"109\" y2=\"161\"/><polygon class=\"arrow b1\" points=\"102,151 114,157 104,164\"/><circle class=\"n\" cx=\"30\" cy=\"55\" r=\"18\"/><circle class=\"n\" cx=\"150\" cy=\"55\" r=\"18\"/><circle class=\"n\" cx=\"30\" cy=\"215\" r=\"18\"/><circle class=\"n\" cx=\"150\" cy=\"215\" r=\"18\"/><circle class=\"n2\" cx=\"90\" cy=\"135\" r=\"20\"/><text class=\"tl\" x=\"90\" y=\"141\" font-size=\"16\" text-anchor=\"middle\">v<\/text><rect class=\"box b1\" x=\"195\" y=\"30\" width=\"275\" height=\"56\" rx=\"10\"/><text class=\"t b1\" x=\"332\" y=\"64\" font-size=\"16\" text-anchor=\"middle\">x ← αAx + β (Katz)<\/text><line class=\"e b2\" x1=\"332\" y1=\"86\" x2=\"332\" y2=\"100\"/><polygon class=\"arrow b2\" points=\"332,112 326,100 338,100\"/><rect class=\"box b2\" x=\"195\" y=\"112\" width=\"275\" height=\"56\" rx=\"10\"/><text class=\"t b2\" x=\"332\" y=\"146\" font-size=\"16\" text-anchor=\"middle\">점수 x를 벡터 H로, W와 σ 추가<\/text><line class=\"e b3\" x1=\"332\" y1=\"168\" x2=\"332\" y2=\"182\"/><polygon class=\"arrow b3\" points=\"332,194 326,182 338,182\"/><rect class=\"box2 b3\" x=\"195\" y=\"194\" width=\"275\" height=\"56\" rx=\"10\"/><text class=\"tb b3\" x=\"332\" y=\"228\" font-size=\"16\" text-anchor=\"middle\">H ← σ(A H W) = GNN<\/text><\/svg>","caption":"이웃 점수를 끌어오는 **전파(Propagation)**에 벡터, 가중치, 활성화를 붙이면 GNN이에요","builds":3},{"kind":"points","head":"이웃에게서 끌어오기 = GNN","items":["노드 중요도를 모르면? 연결된 친구에게서 끌어와요","친구도 모르면 친구의 친구에게서 끌어와요","모든 노드에서 반복하면 식은 '인접행렬 곱하기 특징'이에요","점수 하나를 벡터로, 가중치와 활성화를 붙이면 GNN","그래서 **전파(Propagation)**형 중심성이 GNN의 씨앗이에요"]},{"kind":"english","head":"시험 문장: 고유벡터 중심성","en":"Eigenvector centrality assumes a node is important if it is surrounded by important neighbors, giving $\\lambda c=Ac$.","ko":"고유벡터 중심성은 중요한 이웃에 둘러싸인 노드가 중요하다고 보며, 식은 $\\lambda c=Ac$예요."},{"kind":"english","head":"시험 문장: PageRank","en":"In PageRank, a page distributes its score equally over its outgoing links.","ko":"PageRank에서 페이지는 점수를 나가는 링크에 똑같이 나눠 줘요.","tip":"뒤에 이어 쓰기: so a vote from a page with many outlinks carries less weight."},{"kind":"check","q":"**Damping factor**의 역할은?","choices":["모든 점수를 0으로 만든다","멀리서 온 정보의 가치를 줄여 발산을 막는다","노드 수를 센다","엣지 방향을 바꾼다"],"a":1,"why":"**감쇠 인자(Damping factor)** $\\alpha<1$은 친구의 친구 정보를 덜 쳐서 **카츠 중심성(Katz centrality)**이 발산하지 않게 해요"},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["p.37의 $M$은 인접행렬이라 불리지만 열 합이 1인 **전이 행렬(Transition matrix)**이에요","마이닝 기출은 Katz를 $\\beta(I-\\alpha A^T)^{-1}\\mathbf 1$로 주기도 해요. 주어진 식을 따라요","Katz에서 $\\alpha=1/\\lambda_{max}$, $\\beta=0$이면 고유벡터 중심성과 같아요"]},{"kind":"recap","items":["**고유벡터 중심성(Eigenvector centrality)**: 중요한 이웃이 많으면 중요, $\\lambda\\mathbf c=\\mathbf A\\mathbf c$","**카츠 중심성(Katz centrality)**: **감쇠 인자(Damping factor)** $\\alpha$와 기본 점수 $\\beta$","**페이지랭크(PageRank)**: 점수를 나가는 링크 수로 나눠 전달","점수 **전파(Propagation)**에 벡터, 가중치, 활성화를 붙이면 GNN","오늘의 용어: Eigenvector centrality(고유벡터 중심성), Katz centrality(카츠 중심성), PageRank(페이지랭크), Damping factor(감쇠 인자), Propagation(전파), Transition matrix(전이 행렬)"]}]},{"id":"w1-4","title":"끼리끼리 뭉친 무리: 커뮤니티와 클러스터링 계수","goal":"클리크와 CPM으로 무리를 찾고, 국소, 평균, 전역 클러스터링 계수를 계산할 수 있어요","terms":[{"en":"Community","ko":"커뮤니티","say":"촘촘하게 뭉친 노드 무리"},{"en":"Clique","ko":"클리크","say":"모든 구성원이 서로 직접 연결된 무리"},{"en":"Clique Percolation Method","ko":"클리크 퍼컬레이션","say":"k-1개 노드를 공유하는 k-클리크를 이어 붙이는 방법"},{"en":"Local clustering coefficient","ko":"국소 클러스터링 계수","say":"내 친구들끼리도 친구인 비율"},{"en":"Global clustering coefficient","ko":"전역 클러스터링 계수","say":"그래프 전체 V자 중 닫힌 것의 비율"},{"en":"Closed triplet","ko":"닫힌 삼중항","say":"양 끝까지 이어져 삼각형이 된 V자"}],"slides":[{"kind":"title","big":"끼리끼리 뭉친 무리","sub":"커뮤니티와 클러스터링 계수"},{"kind":"goal","items":["**커뮤니티(Community)**와 **클리크(Clique)**의 뜻을 말할 수 있어요","**클리크 퍼컬레이션(Clique Percolation Method)**으로 겹치는 무리를 찾을 수 있어요","**국소 클러스터링 계수(Local clustering coefficient)**를 계산할 수 있어요","**전역 클러스터링 계수(Global clustering coefficient)**를 계산할 수 있어요"]},{"kind":"analogy","head":"학교 친구 무리","scene":"친구 관계를 그리면 반이나 동아리별로 덩어리가 보여요. 그 덩어리를 찾는 게 커뮤니티 탐지예요.","map":[["반이나 동아리 덩어리","**커뮤니티(Community)**"],["전원이 서로 친구인 모임","**클리크(Clique)**"],["내 친구들끼리도 친구인 정도","**국소 클러스터링 계수(Local clustering coefficient)**"]]},{"kind":"points","head":"앞 단원과 이어 보기","items":["**중심성(Centrality)**은 노드 한 명의 점수였어요","이번엔 여러 노드를 묶는 **커뮤니티(Community)**를 봐요","앞에서 본 **차수(Degree)**가 가지치기 재료로 다시 나와요","기준은 4갈래: 노드 중심, 그룹 중심, 네트워크 중심, 계층 중심","교수님은 녹음에서 이 부분을 따로 설명하지 않고 넘어갔어요"]},{"kind":"points","head":"클리크 찾기의 요령","items":["**클리크(Clique)**는 너무 엄격하고, 최대 클리크 찾기는 NP-hard예요","크기 $k$ 클리크의 구성원은 **차수(Degree)**가 $k-1$ 이상이에요","그보다 친구가 적은 노드는 미리 지워요","지우면 이웃 차수도 줄어 연쇄적으로 지워져요","멱법칙 네트워크에서 특히 효과적이에요"]},{"kind":"steps","head":"직접 해보기: 가지치기","given":"L1 p.45 그래프에서 크기 3 클리크 {1, 2, 3}을 먼저 찾았어요","steps":["1단계. 더 큰 클리크를 찾으려고 차수 $\\le2$인 노드 2와 9를 지워요","2단계. 그러면 1과 3의 차수가 줄어 지워져요","3단계. 이어서 4도 차수가 줄어 지워져요","4단계. 남은 {5, 6, 7, 8}이 서로 모두 연결인지 확인해요"],"answer":"{5, 6, 7, 8}이 크기 4 최대 **클리크(Clique)**예요"},{"kind":"points","head":"클리크 퍼컬레이션(CPM)","items":["크기 $k$ 클리크(예: 삼각형)를 모두 찾아요","노드 $k-1$개를 공유하는 클리크끼리 이어요","이어진 덩어리(연결 성분) 하나가 **커뮤니티(Community)** 하나","한 노드가 두 무리에 겹칠 수 있어요, 겹치는 커뮤니티","이게 **클리크 퍼컬레이션(Clique Percolation Method)**이에요"]},{"kind":"figure","head":"삼각형을 이어 붙여 무리 찾기","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><line class=\"e\" x1=\"30\" y1=\"120\" x2=\"110\" y2=\"70\"/><line class=\"e\" x1=\"110\" y1=\"70\" x2=\"205\" y2=\"85\"/><line class=\"e\" x1=\"110\" y1=\"70\" x2=\"100\" y2=\"175\"/><line class=\"e\" x1=\"110\" y1=\"70\" x2=\"205\" y2=\"190\"/><line class=\"e\" x1=\"205\" y1=\"85\" x2=\"100\" y2=\"175\"/><line class=\"e\" x1=\"205\" y1=\"85\" x2=\"205\" y2=\"190\"/><line class=\"e\" x1=\"205\" y1=\"85\" x2=\"300\" y2=\"135\"/><line class=\"e\" x1=\"100\" y1=\"175\" x2=\"205\" y2=\"190\"/><line class=\"e\" x1=\"205\" y1=\"190\" x2=\"300\" y2=\"135\"/><line class=\"e\" x1=\"300\" y1=\"135\" x2=\"390\" y2=\"60\"/><line class=\"e\" x1=\"300\" y1=\"135\" x2=\"450\" y2=\"135\"/><line class=\"e\" x1=\"390\" y1=\"60\" x2=\"450\" y2=\"135\"/><line class=\"e\" x1=\"390\" y1=\"60\" x2=\"390\" y2=\"215\"/><line class=\"e\" x1=\"450\" y1=\"135\" x2=\"390\" y2=\"215\"/><circle class=\"n\" cx=\"30\" cy=\"120\" r=\"18\"/><text class=\"tl\" x=\"30\" y=\"126\" font-size=\"16\" text-anchor=\"middle\">9<\/text><circle class=\"n\" cx=\"110\" cy=\"70\" r=\"18\"/><text class=\"tl\" x=\"110\" y=\"76\" font-size=\"16\" text-anchor=\"middle\">7<\/text><circle class=\"n\" cx=\"205\" cy=\"85\" r=\"18\"/><text class=\"tl\" x=\"205\" y=\"91\" font-size=\"16\" text-anchor=\"middle\">5<\/text><circle class=\"n\" cx=\"100\" cy=\"175\" r=\"18\"/><text class=\"tl\" x=\"100\" y=\"181\" font-size=\"16\" text-anchor=\"middle\">8<\/text><circle class=\"n\" cx=\"205\" cy=\"190\" r=\"18\"/><text class=\"tl\" x=\"205\" y=\"196\" font-size=\"16\" text-anchor=\"middle\">6<\/text><circle class=\"n\" cx=\"300\" cy=\"135\" r=\"18\"/><text class=\"tl\" x=\"300\" y=\"141\" font-size=\"16\" text-anchor=\"middle\">4<\/text><circle class=\"n\" cx=\"390\" cy=\"60\" r=\"18\"/><text class=\"tl\" x=\"390\" y=\"66\" font-size=\"16\" text-anchor=\"middle\">3<\/text><circle class=\"n\" cx=\"450\" cy=\"135\" r=\"18\"/><text class=\"tl\" x=\"450\" y=\"141\" font-size=\"16\" text-anchor=\"middle\">1<\/text><circle class=\"n\" cx=\"390\" cy=\"215\" r=\"18\"/><text class=\"tl\" x=\"390\" y=\"221\" font-size=\"16\" text-anchor=\"middle\">2<\/text><circle class=\"n3 b1\" cx=\"450\" cy=\"135\" r=\"18\"/><text class=\"tl b1\" x=\"450\" y=\"141\" font-size=\"16\" text-anchor=\"middle\">1<\/text><circle class=\"n3 b1\" cx=\"390\" cy=\"215\" r=\"18\"/><text class=\"tl b1\" x=\"390\" y=\"221\" font-size=\"16\" text-anchor=\"middle\">2<\/text><circle class=\"n3 b1\" cx=\"390\" cy=\"60\" r=\"18\"/><text class=\"tl b1\" x=\"390\" y=\"66\" font-size=\"16\" text-anchor=\"middle\">3<\/text><circle class=\"n3 b1\" cx=\"300\" cy=\"135\" r=\"18\"/><text class=\"tl b1\" x=\"300\" y=\"141\" font-size=\"16\" text-anchor=\"middle\">4<\/text><circle class=\"n2 b2\" cx=\"205\" cy=\"85\" r=\"18\"/><text class=\"tl b2\" x=\"205\" y=\"91\" font-size=\"16\" text-anchor=\"middle\">5<\/text><circle class=\"n2 b2\" cx=\"205\" cy=\"190\" r=\"18\"/><text class=\"tl b2\" x=\"205\" y=\"196\" font-size=\"16\" text-anchor=\"middle\">6<\/text><circle class=\"n2 b2\" cx=\"110\" cy=\"70\" r=\"18\"/><text class=\"tl b2\" x=\"110\" y=\"76\" font-size=\"16\" text-anchor=\"middle\">7<\/text><circle class=\"n2 b2\" cx=\"100\" cy=\"175\" r=\"18\"/><text class=\"tl b2\" x=\"100\" y=\"181\" font-size=\"16\" text-anchor=\"middle\">8<\/text><circle class=\"n2 b2\" cx=\"300\" cy=\"135\" r=\"18\"/><text class=\"tl b2\" x=\"300\" y=\"141\" font-size=\"16\" text-anchor=\"middle\">4<\/text><circle class=\"hl b3\" cx=\"300\" cy=\"135\" r=\"27\"/><text class=\"tb b1\" x=\"400\" y=\"258\" font-size=\"16\" text-anchor=\"middle\">무리 1: {1,2,3,4}<\/text><text class=\"tb b2\" x=\"130\" y=\"258\" font-size=\"16\" text-anchor=\"middle\">무리 2: {4,5,6,7,8}<\/text><text class=\"t b3\" x=\"240\" y=\"25\" font-size=\"16\" text-anchor=\"middle\">4는 겹치고, 9는 어디에도 없어요<\/text><\/svg>","caption":"L1 p.47. 노드 2개를 공유하는 삼각형끼리 이으면 **커뮤니티(Community)** 2개가 나와요","builds":3},{"kind":"formula","head":"국소 클러스터링 계수","tex":"C_i=\\frac{2L_i}{d_i(d_i-1)}=\\frac{L_i}{\\binom{d_i}{2}}","parts":[{"sym":"L_i","say":"내 이웃들 사이에 있는 엣지 수"},{"sym":"d_i","say":"내 **차수(Degree)**, 이웃 수"},{"sym":"\\binom{d_i}{2}","say":"이웃끼리 만들 수 있는 쌍의 수(이웃 4명이면 6)"}],"whole":"이웃끼리 가능한 쌍 중 실제로 친구인 비율이 **국소 클러스터링 계수(Local clustering coefficient)**예요"},{"kind":"formula","head":"평균과 전역 클러스터링 계수","tex":"\\langle C\\rangle=\\frac1N\\sum_i C_i,\\qquad C(G)=\\frac{\\#\\text{closed triplets}}{\\#\\text{connected triplets}}","parts":[{"sym":"\\langle C\\rangle","say":"국소 계수들의 산술평균"},{"sym":"\\text{connected triplet}","say":"가운데 노드에 엣지 두 개가 붙은 V자"},{"sym":"\\text{closed triplet}","say":"양 끝도 이어진 **닫힌 삼중항(Closed triplet)**"}],"whole":"V자 중 닫힌 것의 비율이 **전역 클러스터링 계수(Global clustering coefficient)**예요"},{"kind":"figure","head":"삼각형과 꼬리의 클러스터링 계수","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><line class=\"e\" x1=\"110\" y1=\"50\" x2=\"50\" y2=\"170\"/><line class=\"e\" x1=\"110\" y1=\"50\" x2=\"170\" y2=\"170\"/><line class=\"e\" x1=\"50\" y1=\"170\" x2=\"170\" y2=\"170\"/><line class=\"e\" x1=\"170\" y1=\"170\" x2=\"290\" y2=\"170\"/><circle class=\"n\" cx=\"110\" cy=\"50\" r=\"20\"/><text class=\"tl\" x=\"110\" y=\"56\" font-size=\"16\" text-anchor=\"middle\">A<\/text><circle class=\"n\" cx=\"50\" cy=\"170\" r=\"20\"/><text class=\"tl\" x=\"50\" y=\"176\" font-size=\"16\" text-anchor=\"middle\">B<\/text><circle class=\"n2\" cx=\"170\" cy=\"170\" r=\"20\"/><text class=\"tl\" x=\"170\" y=\"176\" font-size=\"16\" text-anchor=\"middle\">C<\/text><circle class=\"n\" cx=\"290\" cy=\"170\" r=\"20\"/><text class=\"tl\" x=\"290\" y=\"176\" font-size=\"16\" text-anchor=\"middle\">D<\/text><text class=\"tb b1\" x=\"145\" y=\"45\" font-size=\"16\" text-anchor=\"start\">1<\/text><text class=\"tb b1\" x=\"50\" y=\"215\" font-size=\"16\" text-anchor=\"middle\">1<\/text><text class=\"tb b1\" x=\"170\" y=\"215\" font-size=\"16\" text-anchor=\"middle\">1/3<\/text><text class=\"tb b1\" x=\"290\" y=\"215\" font-size=\"16\" text-anchor=\"middle\">0<\/text><text class=\"t b2\" x=\"390\" y=\"70\" font-size=\"16\" text-anchor=\"middle\">평균 = 7/12<\/text><text class=\"t b2\" x=\"390\" y=\"95\" font-size=\"16\" text-anchor=\"middle\">≈ 0.583<\/text><text class=\"t b3\" x=\"390\" y=\"130\" font-size=\"16\" text-anchor=\"middle\">V자 5개 중 닫힘 3개<\/text><text class=\"tb b3\" x=\"390\" y=\"155\" font-size=\"16\" text-anchor=\"middle\">전역 = 3/5 = 0.6<\/text><\/svg>","caption":"노드 옆 숫자가 **국소 클러스터링 계수(Local clustering coefficient)**, 오른쪽이 평균과 전역 값이에요","builds":3},{"kind":"steps","head":"직접 계산: 삼각형 + 꼬리","given":"삼각형 A-B-C와 꼬리 C-D","steps":["1단계. A: 이웃 B, C가 연결, $2\\cdot1/(2\\cdot1)=1$. B도 1","2단계. C: 이웃 A, B, D 중 A-B만 연결, $2\\cdot1/(3\\cdot2)=1/3$","3단계. D: 차수 1이라 0","4단계. 평균 $(1+1+1/3+0)/4=7/12\\approx0.583$","5단계. V자 세기: A 중심 1(닫힘), B 중심 1(닫힘), C 중심 3(닫힘 1)","6단계. 닫힌 3개 / 전체 5개"],"answer":"평균 $0.583$, **전역 클러스터링 계수(Global clustering coefficient)** $3/5=0.6$"},{"kind":"english","head":"시험 문장: 국소 계수","en":"The local clustering coefficient measures how close the neighbors of a node are to forming a clique.","ko":"국소 클러스터링 계수는 노드의 이웃들이 클리크에 얼마나 가까운지 재요.","tip":"식도 같이: $C_i=2L_i/(d_i(d_i-1))$"},{"kind":"english","head":"시험 문장: CPM","en":"The Clique Percolation Method finds overlapping communities by connecting k-cliques that share k-1 nodes.","ko":"CPM은 노드 k-1개를 공유하는 k-클리크를 이어 겹치는 커뮤니티를 찾아요.","tip":"Each triangle contributes three closed triplets, 삼각형 1개는 닫힌 삼중항 3개"},{"kind":"check","q":"**Clique**의 뜻으로 맞는 것은?","choices":["차수가 가장 큰 노드","모든 구성원이 서로 직접 연결된 무리","최단 경로 위 길목","V자 모양 세 노드"],"a":1,"why":"**클리크(Clique)**는 전원이 서로 친구인 완전한 무리예요"},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["평균과 **전역 클러스터링 계수(Global clustering coefficient)**는 값이 다를 수 있어요(0.583과 0.6)","삼각형 1개는 **닫힌 삼중항(Closed triplet)** 3개로 세요","슬라이드 p.50의 평균 0.333은 틀렸고 $13/42\\approx0.310$이 맞아요"]},{"kind":"recap","items":["**커뮤니티(Community)**는 촘촘히 뭉친 노드 무리예요","**클리크(Clique)**는 전원이 서로 친구, 차수로 가지치기해요","**클리크 퍼컬레이션(Clique Percolation Method)**은 겹치는 무리를 찾아요","국소 $2L_i/(d_i(d_i-1))$, 전역은 **닫힌 삼중항(Closed triplet)** 비율이에요","오늘의 용어: Community(커뮤니티), Clique(클리크), Clique Percolation Method(클리크 퍼컬레이션), Local clustering coefficient(국소 클러스터링 계수), Global clustering coefficient(전역 클러스터링 계수), Closed triplet(닫힌 삼중항)"]}]},{"id":"w1-5","title":"두 그래프는 같을까: 동형, 그래플릿, WL 커널","goal":"동형과 불변량을 설명하고, 그래플릿 벡터와 WL 커널 값을 계산할 수 있어요","terms":[{"en":"Isomorphism","ko":"동형","say":"이름표만 바꾸면 똑같아지는 두 그래프"},{"en":"Invariant","ko":"불변량","say":"이름표를 바꿔도 안 변하는 값(노드 수, 엣지 수, 차수)"},{"en":"Graph kernel","ko":"그래프 커널","say":"센 특징 벡터의 내적으로 잰 두 그래프의 닮음"},{"en":"Graphlet","ko":"그래플릿","say":"미리 정해 둔 작은 연결 모양"},{"en":"Color refinement","ko":"색 정제","say":"내 색과 이웃 색 묶음으로 새 색을 주는 반복"},{"en":"WL kernel","ko":"WL 커널","say":"색 정제 후 색별 개수 벡터로 만든 커널"},{"en":"Expressive power","ko":"표현력","say":"서로 다른 구조를 구별하는 능력"}],"slides":[{"kind":"title","big":"두 그래프는 같을까","sub":"동형, 그래플릿, WL 커널"},{"kind":"goal","items":["**동형(Isomorphism)**과 **불변량(Invariant)**을 설명할 수 있어요","**그래플릿(Graphlet)** 개수로 **그래프 커널(Graph kernel)**을 계산할 수 있어요","**색 정제(Color refinement)**로 **WL 커널(WL kernel)**을 계산할 수 있어요","WL이 GNN **표현력(Expressive power)**의 기준인 이유를 알 수 있어요"]},{"kind":"analogy","head":"이름표만 바꾼 같은 반","scene":"두 반의 친구 관계도가 있어요. 학생 이름표만 바꿔 붙였더니 선 모양이 완전히 똑같아졌다면, 두 관계도는 같은 구조예요.","map":[["이름표 바꿔 붙이기","노드 전단사 $f$"],["선 모양이 똑같음","**동형(Isomorphism)**"],["학생 수, 선 수, 친구 수 목록","**불변량(Invariant)**"]]},{"kind":"points","head":"동형의 정확한 뜻","items":["전단사 $f:V_1\\to V_2$가 있어 $a,b$ 인접 $\\Leftrightarrow$ $f(a),f(b)$ 인접","노드 순서를 바꿔 $M(G_1)=M(G_2)$가 되면 **동형(Isomorphism)**","다항 시간 알고리즘은 아직 알려져 있지 않아요","**불변량(Invariant)** 하나라도 다르면 비동형 확정","다 같아도 동형이라는 보장은 없어요"]},{"kind":"formula","head":"그래프 커널","tex":"K(G,G')=\\phi(G)^T\\phi(G')","parts":[{"sym":"\\phi(G)","say":"그래프에서 무언가를 세어 만든 특징 벡터"},{"sym":"\\phi(G)^T\\phi(G')","say":"두 벡터의 내적(칸끼리 곱해 더하기)"},{"sym":"K(G,G')","say":"두 그래프의 닮음 점수, 실수 하나"}],"whole":"무엇을 셀지 정해 벡터로 만들고 내적하면 **그래프 커널(Graph kernel)**이에요"},{"kind":"points","head":"그래프의 Bag-of-Words","items":["노드 개수 자루: 너무 거칠어요","앞에서 본 **차수 분포(Degree distribution)** 자루: 교수님 말로 생각보다 정보가 많아요","예: 차수 자루 [1,2,1]과 [0,2,2]의 커널은 $0+4+2=6$","**그래플릿(Graphlet)** 자루: 작은 모양 사전을 만들고 세요","색 자루: **WL 커널(WL kernel)**, 가장 정교해요"]},{"kind":"figure","head":"크기 3 그래플릿 사전","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><line class=\"e b1\" x1=\"60\" y1=\"60\" x2=\"25\" y2=\"130\"/><line class=\"e b1\" x1=\"60\" y1=\"60\" x2=\"95\" y2=\"130\"/><line class=\"e b1\" x1=\"25\" y1=\"130\" x2=\"95\" y2=\"130\"/><circle class=\"n b1\" cx=\"60\" cy=\"60\" r=\"16\"/><circle class=\"n b1\" cx=\"25\" cy=\"130\" r=\"16\"/><circle class=\"n b1\" cx=\"95\" cy=\"130\" r=\"16\"/><text class=\"tb b1\" x=\"60\" y=\"180\" font-size=\"16\" text-anchor=\"middle\">g1<\/text><text class=\"tm b1\" x=\"60\" y=\"205\" font-size=\"15\" text-anchor=\"middle\">삼각형<\/text><line class=\"e b2\" x1=\"180\" y1=\"60\" x2=\"145\" y2=\"130\"/><line class=\"e b2\" x1=\"180\" y1=\"60\" x2=\"215\" y2=\"130\"/><circle class=\"n b2\" cx=\"180\" cy=\"60\" r=\"16\"/><circle class=\"n b2\" cx=\"145\" cy=\"130\" r=\"16\"/><circle class=\"n b2\" cx=\"215\" cy=\"130\" r=\"16\"/><text class=\"tb b2\" x=\"180\" y=\"180\" font-size=\"16\" text-anchor=\"middle\">g2<\/text><text class=\"tm b2\" x=\"180\" y=\"205\" font-size=\"15\" text-anchor=\"middle\">경로<\/text><line class=\"e b3\" x1=\"265\" y1=\"130\" x2=\"335\" y2=\"130\"/><circle class=\"n b3\" cx=\"300\" cy=\"60\" r=\"16\"/><circle class=\"n b3\" cx=\"265\" cy=\"130\" r=\"16\"/><circle class=\"n b3\" cx=\"335\" cy=\"130\" r=\"16\"/><text class=\"tb b3\" x=\"300\" y=\"180\" font-size=\"16\" text-anchor=\"middle\">g3<\/text><text class=\"tm b3\" x=\"300\" y=\"205\" font-size=\"15\" text-anchor=\"middle\">엣지 1개<\/text><circle class=\"n b4\" cx=\"420\" cy=\"60\" r=\"16\"/><circle class=\"n b4\" cx=\"385\" cy=\"130\" r=\"16\"/><circle class=\"n b4\" cx=\"455\" cy=\"130\" r=\"16\"/><text class=\"tb b4\" x=\"420\" y=\"180\" font-size=\"16\" text-anchor=\"middle\">g4<\/text><text class=\"tm b4\" x=\"420\" y=\"205\" font-size=\"15\" text-anchor=\"middle\">엣지 0개<\/text><text class=\"tb b4\" x=\"240\" y=\"250\" font-size=\"16\" text-anchor=\"middle\">k=3이면 4종, k=4면 11종<\/text><\/svg>","caption":"**그래플릿(Graphlet)** 사전. $g_1$ 삼각형은 앞 단원의 크기 3 **클리크(Clique)**예요","builds":4},{"kind":"steps","head":"직접 계산: 그래플릿 벡터","given":"노드 5개, 엣지 AB, AC, BC, CE, ED (p.79)","steps":["1단계. 3노드 조합은 $\\binom53=10$개","2단계. 삼각형 $g_1$: ABC, 1개","3단계. 엣지 2개 경로 $g_2$: ACE, BCE, CDE, 3개","4단계. 엣지 1개 $g_3$: ABD, ABE, ACD, ADE, BCD, BDE, 6개","5단계. 엣지 0개 $g_4$: 0개, 합 $1+3+6+0=10$ 검산"],"answer":"$\\mathbf f_G=(1,3,6,0)^T$"},{"kind":"formula","head":"WL 색 정제","tex":"c^{(k+1)}(v)=\\mathrm{HASH}\\Big(\\big\\{c^{(k)}(v),\\ \\{c^{(k)}(u)\\}_{u\\in N(v)}\\big\\}\\Big)","parts":[{"sym":"c^{(k)}(v)","say":"k번째 반복에서 노드 v의 색(이름표)"},{"sym":"\\{c^{(k)}(u)\\}_{u\\in N(v)}","say":"이웃들 색의 다중집합"},{"sym":"\\mathrm{HASH}","say":"다른 입력엔 다른 새 색을 주는 함수"},{"sym":"c^{(K)}(v)","say":"K번 뒤 색은 K홉 구조를 담아요"}],"whole":"내 색과 이웃 색 묶음을 새 색으로 바꾸는 반복이 **색 정제(Color refinement)**예요"},{"kind":"analogy","head":"WL은 자기소개 고치기","scene":"'나는 A야'에서 시작해 'B, C, D를 친구로 둔 A야'로 소개를 고쳐요. 반복할수록 소개에 더 넓은 동네 모양이 담겨요.","map":[["자기소개","노드 색"],["친구 목록을 붙여 고친 소개","**색 정제(Color refinement)** 1회"],["옆에서 끌어오기","앞 단원의 점수 **전파(Propagation)**와 같은 모양"],["소개 종류별 인원수 비교","**WL 커널(WL kernel)**"]]},{"kind":"figure","head":"색 정제 한 번 해보기","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text class=\"tb\" x=\"150\" y=\"40\" font-size=\"16\" text-anchor=\"middle\">경로<\/text><text class=\"tb\" x=\"380\" y=\"25\" font-size=\"16\" text-anchor=\"middle\">삼각형<\/text><line class=\"e\" x1=\"60\" y1=\"100\" x2=\"150\" y2=\"100\"/><line class=\"e\" x1=\"150\" y1=\"100\" x2=\"240\" y2=\"100\"/><line class=\"e\" x1=\"380\" y1=\"60\" x2=\"330\" y2=\"150\"/><line class=\"e\" x1=\"380\" y1=\"60\" x2=\"430\" y2=\"150\"/><line class=\"e\" x1=\"330\" y1=\"150\" x2=\"430\" y2=\"150\"/><circle class=\"n\" cx=\"60\" cy=\"100\" r=\"20\"/><text class=\"tl\" x=\"60\" y=\"106\" font-size=\"16\" text-anchor=\"middle\">1<\/text><circle class=\"n\" cx=\"150\" cy=\"100\" r=\"20\"/><text class=\"tl\" x=\"150\" y=\"106\" font-size=\"16\" text-anchor=\"middle\">1<\/text><circle class=\"n\" cx=\"240\" cy=\"100\" r=\"20\"/><text class=\"tl\" x=\"240\" y=\"106\" font-size=\"16\" text-anchor=\"middle\">1<\/text><circle class=\"n\" cx=\"380\" cy=\"60\" r=\"20\"/><text class=\"tl\" x=\"380\" y=\"66\" font-size=\"16\" text-anchor=\"middle\">1<\/text><circle class=\"n\" cx=\"330\" cy=\"150\" r=\"20\"/><text class=\"tl\" x=\"330\" y=\"156\" font-size=\"16\" text-anchor=\"middle\">1<\/text><circle class=\"n\" cx=\"430\" cy=\"150\" r=\"20\"/><text class=\"tl\" x=\"430\" y=\"156\" font-size=\"16\" text-anchor=\"middle\">1<\/text><circle class=\"n3 b1\" cx=\"60\" cy=\"100\" r=\"20\"/><text class=\"tl b1\" x=\"60\" y=\"106\" font-size=\"16\" text-anchor=\"middle\">2<\/text><circle class=\"n2 b1\" cx=\"150\" cy=\"100\" r=\"20\"/><text class=\"tl b1\" x=\"150\" y=\"106\" font-size=\"16\" text-anchor=\"middle\">3<\/text><circle class=\"n3 b1\" cx=\"240\" cy=\"100\" r=\"20\"/><text class=\"tl b1\" x=\"240\" y=\"106\" font-size=\"16\" text-anchor=\"middle\">2<\/text><circle class=\"n2 b1\" cx=\"380\" cy=\"60\" r=\"20\"/><text class=\"tl b1\" x=\"380\" y=\"66\" font-size=\"16\" text-anchor=\"middle\">3<\/text><circle class=\"n2 b1\" cx=\"330\" cy=\"150\" r=\"20\"/><text class=\"tl b1\" x=\"330\" y=\"156\" font-size=\"16\" text-anchor=\"middle\">3<\/text><circle class=\"n2 b1\" cx=\"430\" cy=\"150\" r=\"20\"/><text class=\"tl b1\" x=\"430\" y=\"156\" font-size=\"16\" text-anchor=\"middle\">3<\/text><text class=\"t b2\" x=\"150\" y=\"200\" font-size=\"16\" text-anchor=\"middle\">φ = (3, 2, 1)<\/text><text class=\"t b2\" x=\"380\" y=\"200\" font-size=\"16\" text-anchor=\"middle\">φ = (3, 0, 3)<\/text><text class=\"tb b3\" x=\"240\" y=\"250\" font-size=\"16\" text-anchor=\"middle\">K = 3×3 + 2×0 + 1×3 = 12<\/text><\/svg>","caption":"처음엔 모두 색 1, **색 정제(Color refinement)** 1회 뒤 경로는 끝(2)과 가운데(3)가 갈려요","builds":3},{"kind":"steps","head":"직접 계산: WL 커널","given":"경로 A-B-C와 삼각형 X-Y-Z, 처음 색은 모두 1","steps":["1단계. 경로 A, C는 (1, {1})이라 새 색 2","2단계. 경로 B는 (1, {1,1})이라 새 색 3","3단계. 삼각형은 모두 (1, {1,1})이라 색 3","4단계. 모든 반복의 색 1, 2, 3 개수: 경로 $(3,2,1)$, 삼각형 $(3,0,3)$","5단계. $K=3\\cdot3+2\\cdot0+1\\cdot3=12$"],"answer":"색 분포가 달라 두 그래프는 비동형이 확정돼요"},{"kind":"compare","head":"그래플릿 커널과 WL 커널","cols":["구분","**그래플릿(Graphlet)** 커널","**WL 커널(WL kernel)**"],"rows":[["세는 것","그래플릿 자루","색 자루"],["비용","크다, $n^k$","효율적, 엣지 수 단계"],["보는 범위","크기 $k$ 모양","$K$홉 구조"],["GNN과 관계","간접","밀접, **표현력(Expressive power)**의 기준"]]},{"kind":"english","head":"시험 문장: WL","en":"The WL kernel refines each node color by hashing its own color with the multiset of its neighbors' colors.","ko":"WL 커널은 자기 색과 이웃 색 다중집합을 해시해 노드 색을 정제해요.","tip":"이어서: so after K iterations a color encodes the K-hop neighborhood."},{"kind":"english","head":"시험 문장: WL과 GNN","en":"WL relabeling is closely related to GNNs, because a GNN layer also aggregates its neighbors' representations.","ko":"GNN 층도 이웃 표현을 모아 노드를 갱신하므로 WL 재레이블링은 GNN과 밀접해요.","tip":"Invariants can prove non-isomorphism but not isomorphism. 이 문장도 같이"},{"kind":"check","q":"**Invariant**에 대한 설명으로 맞는 것은?","choices":["하나라도 다르면 두 그래프는 비동형이다","모두 같으면 반드시 동형이다","노드 이름에 따라 값이 바뀐다"],"a":0,"why":"**불변량(Invariant)**은 비동형은 증명하지만 **동형(Isomorphism)**은 증명하지 못해요"},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["WL 색이 같아도 **동형(Isomorphism)** 보장은 없어요. 6-사이클과 삼각형 2개는 영원히 같은 색","그래프 수준 **그래플릿(Graphlet)**은 엣지 0개 모양도 세요. 노드 수준은 연결된 모양만","p.77 마지막 불릿의 Graph kernel은 Graphlet kernel의 오타예요"]},{"kind":"recap","items":["**동형(Isomorphism)**: 이름표만 바꾸면 같아지는 그래프, **불변량(Invariant)**은 비동형만 증명","**그래프 커널(Graph kernel)**: 센 벡터의 내적 $\\phi(G)^T\\phi(G')$","**그래플릿(Graphlet)** 커널은 $n^k$로 비싸고, **WL 커널(WL kernel)**은 효율적","**색 정제(Color refinement)**는 GNN 이웃 집계와 같은 모양, **표현력(Expressive power)**의 기준","오늘의 용어: Isomorphism(동형), Invariant(불변량), Graph kernel(그래프 커널), Graphlet(그래플릿), Color refinement(색 정제), WL kernel(WL 커널), Expressive power(표현력)"]}]},{"id":"w1-6","title":"노드를 좌표로: 특징 공학에서 표현 학습으로","goal":"특징 공학과 표현 학습을 비교하고, 얕은 인코딩을 조회표 계산으로 보일 수 있어요","terms":[{"en":"Feature engineering","ko":"특징 공학","say":"사람이 손으로 특징을 만드는 일"},{"en":"Representation learning","ko":"표현 학습","say":"특징을 모델이 스스로 배우는 일"},{"en":"Node embedding","ko":"노드 임베딩","say":"노드마다 주는 d차원 좌표 벡터"},{"en":"Encoder","ko":"인코더","say":"노드를 벡터로 바꾸는 함수 ENC"},{"en":"Similarity","ko":"유사도","say":"그래프에서 두 노드가 비슷한 정도"},{"en":"Shallow encoding","ko":"얕은 인코딩","say":"노드별 벡터를 표에 두고 직접 고치는 방식"},{"en":"Lookup table","ko":"조회표","say":"노드 번호로 열을 꺼내는 큰 표 Z"},{"en":"Task-independent","ko":"작업 독립적","say":"특정 과제에 묶이지 않고 두루 쓰임"}],"slides":[{"kind":"title","big":"노드를 좌표로 바꾸기","sub":"특징 공학에서 표현 학습으로, 얕은 인코딩"},{"kind":"goal","items":["**특징 공학(Feature engineering)**과 **표현 학습(Representation learning)**을 비교할 수 있어요","**노드 임베딩(Node embedding)**의 목표를 식으로 말할 수 있어요","**얕은 인코딩(Shallow encoding)**을 **조회표(Lookup table)** 계산으로 보일 수 있어요"]},{"kind":"analogy","head":"학생 카드 만들기","scene":"선생님이 학생마다 카드를 써요. 예전엔 선생님이 키, 성적 같은 항목을 골라 적었고, 이제는 컴퓨터가 알아서 좋은 숫자를 채워요.","map":[["선생님이 항목을 골라 적기","**특징 공학(Feature engineering)**"],["컴퓨터가 숫자를 스스로 채우기","**표현 학습(Representation learning)**"],["학생 한 명의 숫자 카드","**노드 임베딩(Node embedding)**"],["카드 보관함","**조회표(Lookup table)**"]]},{"kind":"figure","head":"특징을 누가 만드나","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text class=\"tm\" x=\"20\" y=\"30\" font-size=\"14\" text-anchor=\"start\">예전<\/text><rect class=\"box\" x=\"20\" y=\"40\" width=\"80\" height=\"50\" rx=\"10\"/><text class=\"t\" x=\"60\" y=\"71\" font-size=\"15\" text-anchor=\"middle\">그래프<\/text><rect class=\"box\" x=\"125\" y=\"40\" width=\"150\" height=\"50\" rx=\"10\"/><text class=\"t\" x=\"200\" y=\"71\" font-size=\"15\" text-anchor=\"middle\">손으로 만든 특징<\/text><rect class=\"box\" x=\"300\" y=\"40\" width=\"90\" height=\"50\" rx=\"10\"/><text class=\"t\" x=\"345\" y=\"71\" font-size=\"15\" text-anchor=\"middle\">SVM 등<\/text><rect class=\"box\" x=\"415\" y=\"40\" width=\"65\" height=\"50\" rx=\"10\"/><text class=\"t\" x=\"447\" y=\"71\" font-size=\"15\" text-anchor=\"middle\">예측<\/text><line class=\"e\" x1=\"100\" y1=\"65\" x2=\"113\" y2=\"65\"/><polygon class=\"arrow\" points=\"125,65 113,71 113,59\"/><line class=\"e\" x1=\"275\" y1=\"65\" x2=\"288\" y2=\"65\"/><polygon class=\"arrow\" points=\"300,65 288,71 288,59\"/><line class=\"e\" x1=\"390\" y1=\"65\" x2=\"403\" y2=\"65\"/><polygon class=\"arrow\" points=\"415,65 403,71 403,59\"/><text class=\"tm b1\" x=\"20\" y=\"120\" font-size=\"14\" text-anchor=\"start\">이제<\/text><rect class=\"box b1\" x=\"20\" y=\"130\" width=\"80\" height=\"50\" rx=\"10\"/><text class=\"t b1\" x=\"60\" y=\"161\" font-size=\"15\" text-anchor=\"middle\">그래프<\/text><rect class=\"box2 b1\" x=\"125\" y=\"130\" width=\"150\" height=\"50\" rx=\"10\"/><text class=\"t b1\" x=\"200\" y=\"161\" font-size=\"15\" text-anchor=\"middle\">학습한 임베딩<\/text><rect class=\"box b1\" x=\"300\" y=\"130\" width=\"90\" height=\"50\" rx=\"10\"/><text class=\"t b1\" x=\"345\" y=\"161\" font-size=\"15\" text-anchor=\"middle\">모델<\/text><rect class=\"box b1\" x=\"415\" y=\"130\" width=\"65\" height=\"50\" rx=\"10\"/><text class=\"t b1\" x=\"447\" y=\"161\" font-size=\"15\" text-anchor=\"middle\">예측<\/text><line class=\"e b1\" x1=\"100\" y1=\"155\" x2=\"113\" y2=\"155\"/><polygon class=\"arrow b1\" points=\"125,155 113,161 113,149\"/><line class=\"e b1\" x1=\"275\" y1=\"155\" x2=\"288\" y2=\"155\"/><polygon class=\"arrow b1\" points=\"300,155 288,161 288,149\"/><line class=\"e b1\" x1=\"390\" y1=\"155\" x2=\"403\" y2=\"155\"/><polygon class=\"arrow b1\" points=\"415,155 403,161 403,149\"/><text class=\"tb b2\" x=\"240\" y=\"230\" font-size=\"16\" text-anchor=\"middle\">특징을 매번 새로 설계할 필요가 없어요<\/text><\/svg>","caption":"노드 분류, 링크 예측에 쓰는 파이프라인. **특징 공학(Feature engineering)** 자리를 **표현 학습(Representation learning)**이 대신해요","builds":2},{"kind":"points","head":"앞 단원들이 전부 특징 재료였어요","items":["중요도 기반: **차수(Degree)**, **중심성(Centrality)**","구조 기반: **국소 클러스터링 계수(Local clustering coefficient)**, **그래플릿(Graphlet)**","그래프 수준: 그래플릿 커널, **WL 커널(WL kernel)**","이걸 사람이 고르는 게 **특징 공학(Feature engineering)**이에요","교수님: 휴리스틱 특징도 여전히 중요, GNN 설계의 바탕이에요"]},{"kind":"points","head":"시대의 흐름","items":["예전: 사람이 특징을 손으로 만들었어요","2018~2019년까지: 얕은 임베딩(shallow embedding) 모델","2020년 이후: GNN","**표현 학습(Representation learning)**은 **작업 독립적(Task-independent)** 특징을 자동으로 배워요"]},{"kind":"formula","head":"노드 임베딩의 목표","tex":"\\text{similarity}(u,v)\\approx\\mathbf z_v^T\\mathbf z_u","parts":[{"sym":"\\mathbf z_u","say":"노드 u의 **노드 임베딩(Node embedding)**, d차원 벡터"},{"sym":"\\mathbf z_v^T\\mathbf z_u","say":"두 벡터의 내적, 디코더가 내는 점수"},{"sym":"\\text{similarity}(u,v)","say":"원래 그래프에서 두 노드의 **유사도(Similarity)**"}],"whole":"그래프에서 비슷한 두 노드는 벡터 내적도 크게 만드는 게 목표예요"},{"kind":"points","head":"정해야 할 두 가지","items":["**인코더(Encoder)**: 노드를 벡터로 바꾸는 함수 ENC","**유사도(Similarity)**: 그래프에서 비슷하다의 뜻","연결되어 있으면? 이웃을 공유하면? 역할이 같으면?","이 선택에 따라 뒤의 모델들이 갈라져요","노드 레이블도 노드 특징도 쓰지 않는 비지도 방식이에요"]},{"kind":"formula","head":"얕은 인코딩","tex":"\\mathrm{ENC}(v)=\\mathbf z_v=\\mathbf Z\\cdot v,\\qquad \\mathbf Z\\in\\mathbb R^{d\\times|V|}","parts":[{"sym":"\\mathbf Z","say":"**조회표(Lookup table)**, 열 하나가 노드 하나"},{"sym":"v","say":"노드 v 자리만 1인 one-hot 벡터"},{"sym":"d","say":"임베딩 차원"},{"sym":"|V|","say":"노드 수"}],"whole":"표에서 노드 열을 꺼내는 게 **얕은 인코딩(Shallow encoding)**, 학습은 표 숫자를 직접 고쳐요"},{"kind":"figure","head":"조회표에서 열 꺼내기","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text class=\"tb\" x=\"75\" y=\"100\" font-size=\"20\" text-anchor=\"middle\">Z<\/text><text class=\"tm\" x=\"75\" y=\"125\" font-size=\"14\" text-anchor=\"middle\">d=2, |V|=3<\/text><text class=\"tb\" x=\"180\" y=\"45\" font-size=\"16\" text-anchor=\"middle\">z1<\/text><rect class=\"box\" x=\"150\" y=\"60\" width=\"60\" height=\"40\" rx=\"6\"/><text class=\"t\" x=\"180\" y=\"86\" font-size=\"16\" text-anchor=\"middle\">1<\/text><rect class=\"box\" x=\"150\" y=\"105\" width=\"60\" height=\"40\" rx=\"6\"/><text class=\"t\" x=\"180\" y=\"131\" font-size=\"16\" text-anchor=\"middle\">0<\/text><text class=\"tb\" x=\"250\" y=\"45\" font-size=\"16\" text-anchor=\"middle\">z2<\/text><rect class=\"box\" x=\"220\" y=\"60\" width=\"60\" height=\"40\" rx=\"6\"/><text class=\"t\" x=\"250\" y=\"86\" font-size=\"16\" text-anchor=\"middle\">0<\/text><rect class=\"box\" x=\"220\" y=\"105\" width=\"60\" height=\"40\" rx=\"6\"/><text class=\"t\" x=\"250\" y=\"131\" font-size=\"16\" text-anchor=\"middle\">1<\/text><text class=\"tb\" x=\"320\" y=\"45\" font-size=\"16\" text-anchor=\"middle\">z3<\/text><rect class=\"box\" x=\"290\" y=\"60\" width=\"60\" height=\"40\" rx=\"6\"/><text class=\"t\" x=\"320\" y=\"86\" font-size=\"16\" text-anchor=\"middle\">2<\/text><rect class=\"box\" x=\"290\" y=\"105\" width=\"60\" height=\"40\" rx=\"6\"/><text class=\"t\" x=\"320\" y=\"131\" font-size=\"16\" text-anchor=\"middle\">1<\/text><rect class=\"hl b1\" x=\"283\" y=\"28\" width=\"74\" height=\"122\" rx=\"8\"/><text class=\"t b1\" x=\"240\" y=\"190\" font-size=\"16\" text-anchor=\"middle\">v=3의 one-hot (0,0,1)이 3번째 열을 꺼내요<\/text><text class=\"t b2\" x=\"240\" y=\"225\" font-size=\"16\" text-anchor=\"middle\">z1, z3 내적 = 1×2 + 0×1 = 2<\/text><text class=\"t b3\" x=\"240\" y=\"255\" font-size=\"16\" text-anchor=\"middle\">z2, z3 내적 = 0×2 + 1×1 = 1<\/text><\/svg>","caption":"**얕은 인코딩(Shallow encoding)**은 **조회표(Lookup table)** $\\mathbf Z$에서 노드 열을 꺼내요","builds":3},{"kind":"steps","head":"직접 계산: 조회와 손실","given":"노드 3개, $d=2$, $\\mathbf z_1=(1,0)$, $\\mathbf z_2=(0,1)$, $\\mathbf z_3=(2,1)$","steps":["1단계. $v=3$의 one-hot $(0,0,1)$을 곱하면 세 번째 열 $(2,1)$","2단계. $\\mathbf z_1^T\\mathbf z_3=1\\cdot2+0\\cdot1=2$","3단계. $\\mathbf z_2^T\\mathbf z_3=0\\cdot2+1\\cdot1=1$","4단계. 엣지가 1-3만 있으면 $A_{13}=1$, $A_{23}=0$","5단계. 손실 항 $(2-1)^2=1$, $(1-0)^2=1$, 이 차이를 줄이게 $\\mathbf Z$를 고쳐요","6단계. 노드 $10^6$개, $d=128$이면 파라미터 $1.28\\times10^8$개"],"answer":"**얕은 인코딩(Shallow encoding)**의 파라미터는 노드 수에 비례, $O(|V|)$"},{"kind":"formula","head":"인접 기반(행렬 분해) 방법","tex":"\\mathcal L=\\sum_{(u,v)\\in V\\times V}\\big\\|\\mathbf z_u^{\\top}\\mathbf z_v-\\mathbf A_{u,v}\\big\\|^2","parts":[{"sym":"\\mathbf z_u^{\\top}\\mathbf z_v","say":"임베딩 내적, 모델이 본 **유사도(Similarity)**"},{"sym":"\\mathbf A_{u,v}","say":"인접행렬 값, 연결이면 1"},{"sym":"\\sum_{(u,v)\\in V\\times V}","say":"모든 노드 쌍에 대해 더하기"}],"whole":"내적이 인접행렬 값과 같아지게 표를 고치는 게 인접 기반 방법이에요"},{"kind":"points","head":"인접 기반 방법의 한계","items":["직접 연결 안 된 노드는 가까워도 유사도를 못 잡아요","교수님: 연결성을 보존하려 인접행렬을 분해하는 생각이에요","교수님: 노드가 많아지면 계산 부하가 엄청 커져요","그래서 다음 단원의 랜덤워크 계열이 나와요"]},{"kind":"english","head":"시험 문장: 표현 학습","en":"Representation learning learns task-independent node embeddings without feature engineering every time.","ko":"표현 학습은 작업 독립적인 노드 임베딩을 자동으로 배우므로 매번 특징 공학을 할 필요가 없어요.","tip":"Goal: the dot product of two embeddings approximates node similarity."},{"kind":"english","head":"시험 문장: 얕은 인코더","en":"A shallow encoder is an embedding lookup table: each node has its own column in Z, optimized directly.","ko":"얕은 인코더는 임베딩 조회표로, 각 노드가 Z에서 자기 열을 가지며 그 벡터를 직접 최적화해요."},{"kind":"check","q":"**Shallow encoding**의 뜻은?","choices":["층을 많이 쌓은 신경망","노드별 벡터를 조회표에 두고 직접 고치는 방식","사람이 특징을 고르는 방식","그래프를 이미지로 바꾸는 방식"],"a":1,"why":"**얕은 인코딩(Shallow encoding)**은 $\\mathbf Z$의 노드 열을 꺼내 쓰는 **조회표(Lookup table)**예요"},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["얕다(shallow)는 층이 없다는 뜻이지 성능이 나쁘단 뜻이 아니에요. 교수님: 성능은 준수해요","슬라이드 p.11 식 우변의 $z_u^Tz_u$는 $z_u^Tz_v$의 오타예요"]},{"kind":"recap","items":["**특징 공학(Feature engineering)**은 사람이, **표현 학습(Representation learning)**은 모델이 특징을 만들어요","**노드 임베딩(Node embedding)** 목표: **유사도(Similarity)** $\\approx\\mathbf z_v^T\\mathbf z_u$","**얕은 인코딩(Shallow encoding)** = **조회표(Lookup table)**에서 열 꺼내기, **인코더(Encoder)**가 가장 단순한 경우","인접 기반 방법은 직접 연결만 봐서 먼 유사도를 놓쳐요","오늘의 용어: Feature engineering(특징 공학), Representation learning(표현 학습), Node embedding(노드 임베딩), Encoder(인코더), Similarity(유사도), Shallow encoding(얕은 인코딩), Lookup table(조회표), Task-independent(작업 독립적)"]}]},{"id":"w1-7","title":"그래프 위를 산책해요: 랜덤워크와 DeepWalk","goal":"랜덤워크로 유사도를 정의하고, DeepWalk의 소프트맥스 확률과 SGD 갱신을 계산할 수 있어요","terms":[{"en":"Random walk","ko":"랜덤워크","say":"이웃을 무작위로 골라 걷는 산책"},{"en":"DeepWalk","ko":"딥워크","say":"편향 없는 랜덤워크 + 스킵그램으로 노드 임베딩"},{"en":"word2vec","ko":"워드투벡","say":"문장에서 단어 벡터를 배우는 방법"},{"en":"Skip-gram","ko":"스킵그램","say":"가운데 단어로 주변 단어를 맞히는 학습"},{"en":"Co-occurrence","ko":"동시 출현","say":"같은 워크 문맥에 함께 나타남"},{"en":"Softmax","ko":"소프트맥스","say":"점수들을 합이 1인 확률로 바꾸는 식"},{"en":"Unbiased","ko":"편향 없는","say":"이웃을 모두 똑같은 확률로 고름"}],"slides":[{"kind":"title","big":"그래프 위를 산책해요","sub":"랜덤워크와 DeepWalk"},{"kind":"goal","items":["**랜덤워크(Random walk)**로 비슷함을 다시 정의할 수 있어요","**딥워크(DeepWalk)**가 **워드투벡(word2vec)**의 **스킵그램(Skip-gram)**을 빌리는 법을 말할 수 있어요","**소프트맥스(Softmax)** 확률과 SGD 갱신을 계산할 수 있어요"]},{"kind":"points","head":"앞 단원 다시 부르기","items":["**얕은 인코딩(Shallow encoding)**은 노드마다 **조회표(Lookup table)** 열을 뒀어요","인접 기반 방법은 직접 연결만 **유사도(Similarity)**로 봤어요","그래서 공통 친구로 가까운 노드를 놓쳤죠","오늘은 산책으로 비슷함을 다시 정의해요"]},{"kind":"analogy","head":"동네 산책 일기","scene":"매일 동네를 무작위로 산책하며 지나친 가게를 적어요. 일기에 자주 함께 나오는 가게끼리는 가까운 사이겠죠.","map":[["무작위 산책","**랜덤워크(Random walk)**"],["산책 일기 한 줄","노드 문장(워크)"],["일기에 함께 자주 나옴","**동시 출현(Co-occurrence)**"],["가게마다 좌표 배우기","노드 임베딩 학습"]]},{"kind":"formula","head":"랜덤워크로 정한 유사도","tex":"\\mathbf z_u^T\\mathbf z_v\\approx P_R(v\\mid u)","parts":[{"sym":"R","say":"걷는 전략, 어떤 **랜덤워크(Random walk)**인지"},{"sym":"P_R(v\\mid u)","say":"u에서 출발한 산책이 v를 지날 확률"},{"sym":"\\mathbf z_u^T\\mathbf z_v","say":"두 임베딩의 내적"}],"whole":"u에서 출발해 v를 자주 지나면 두 벡터 내적을 크게 만들어요"},{"kind":"points","head":"왜 랜덤워크가 좋을까","items":["표현력: 1홉뿐 아니라 여러 홉 떨어진 구조까지 담아요","효율성: 모든 쌍 대신 워크에 함께 나온 쌍만 학습해요","**동시 출현(Co-occurrence)** 빈도가 **유사도(Similarity)** 지표예요","워크 수 $k$가 크면 더 많이 탐색, 길이 $l$이 크면 먼 노드도 비슷하다고 봐요"]},{"kind":"points","head":"교수님: 왜 굳이 샘플링할까","items":["**워드투벡(word2vec)**은 샘플링이 필요 없어요. 문장이 원래 단어의 줄이니까요","그래프는 노드가 불규칙하게 이어져 줄 모양이 없어요","그래서 이웃을 폴짝폴짝 타며 시퀀스를 만들어요","구조 정보 손실? 샘플링을 엄청 많이 해서 대응해요","그 뒤는 그냥 word2vec을 적용하면 돼요"]},{"kind":"figure","head":"산책 한 번 따라가기","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><line class=\"e\" x1=\"60\" y1=\"200\" x2=\"150\" y2=\"95\"/><line class=\"e\" x1=\"150\" y1=\"95\" x2=\"265\" y2=\"160\"/><line class=\"e\" x1=\"265\" y1=\"160\" x2=\"360\" y2=\"75\"/><line class=\"e\" x1=\"265\" y1=\"160\" x2=\"400\" y2=\"235\"/><line class=\"e\" x1=\"60\" y1=\"200\" x2=\"165\" y2=\"245\"/><line class=\"e\" x1=\"150\" y1=\"95\" x2=\"165\" y2=\"245\"/><line class=\"e2 b1\" x1=\"73\" y1=\"185\" x2=\"129\" y2=\"119\"/><polygon class=\"arrow b1\" points=\"137,110 134,123 125,115\"/><line class=\"e2 b2\" x1=\"167\" y1=\"105\" x2=\"237\" y2=\"144\"/><polygon class=\"arrow b2\" points=\"248,150 234,149 240,139\"/><line class=\"e2 b3\" x1=\"276\" y1=\"142\" x2=\"332\" y2=\"92\"/><polygon class=\"arrow b3\" points=\"341,84 336,96 328,87\"/><line class=\"e2 b3\" x1=\"349\" y1=\"93\" x2=\"293\" y2=\"143\"/><polygon class=\"arrow b3\" points=\"284,151 289,139 297,148\"/><line class=\"e2 b4\" x1=\"282\" y1=\"170\" x2=\"372\" y2=\"219\"/><polygon class=\"arrow b4\" points=\"383,225 369,225 375,214\"/><circle class=\"n2\" cx=\"60\" cy=\"200\" r=\"20\"/><text class=\"tl\" x=\"60\" y=\"206\" font-size=\"16\" text-anchor=\"middle\">s<\/text><circle class=\"n\" cx=\"150\" cy=\"95\" r=\"20\"/><text class=\"tl\" x=\"150\" y=\"101\" font-size=\"16\" text-anchor=\"middle\">5<\/text><circle class=\"n\" cx=\"265\" cy=\"160\" r=\"20\"/><text class=\"tl\" x=\"265\" y=\"166\" font-size=\"16\" text-anchor=\"middle\">8<\/text><circle class=\"n\" cx=\"360\" cy=\"75\" r=\"20\"/><text class=\"tl\" x=\"360\" y=\"81\" font-size=\"16\" text-anchor=\"middle\">9<\/text><circle class=\"n\" cx=\"400\" cy=\"235\" r=\"20\"/><text class=\"tl\" x=\"400\" y=\"241\" font-size=\"16\" text-anchor=\"middle\">11<\/text><circle class=\"n\" cx=\"165\" cy=\"245\" r=\"20\"/><text class=\"tl\" x=\"165\" y=\"251\" font-size=\"16\" text-anchor=\"middle\">3<\/text><text class=\"tm b3\" x=\"410\" y=\"130\" font-size=\"15\" text-anchor=\"middle\">되돌아가기도 허용<\/text><text class=\"tb b4\" x=\"20\" y=\"30\" font-size=\"17\" text-anchor=\"start\">워크 = 문장: s 5 8 9 8 11<\/text><\/svg>","caption":"L1 p.98의 **랜덤워크(Random walk)**. 이웃을 무작위로 골라 걸은 순서가 곧 문장이에요","builds":4},{"kind":"compare","head":"word2vec과 DeepWalk 짝 맞추기","cols":["**워드투벡(word2vec)**","**딥워크(DeepWalk)**"],"rows":[["단어","노드"],["문장(원래 순서가 있음)","**랜덤워크(Random walk)**(샘플링해 만듦)"],["윈도 안 주변 단어","워크 위 주변 노드 $N_R(u)$"],["단어 벡터","노드 임베딩 $\\mathbf z_u$"]]},{"kind":"points","head":"DeepWalk 레시피 세 줄","items":["1. 각 노드에서 길이 $l$의 **편향 없는(Unbiased)** 워크를 $k$번","2. 워크를 문장으로 보고 **스킵그램(Skip-gram)** 학습","3. SGD로 임베딩 갱신","스킵그램: 가운데 노드를 보고 주변 노드를 맞혀요","원 논문(Perozzi et al.)은 계층적 소프트맥스를 썼어요"]},{"kind":"formula","head":"DeepWalk 목적 함수","tex":"\\mathcal L=\\sum_{u\\in V}\\sum_{v\\in N_R(u)}-\\log P(v\\mid\\mathbf z_u),\\quad P(v\\mid\\mathbf z_u)=\\frac{\\exp(\\mathbf z_u^T\\mathbf z_v)}{\\sum_{n\\in V}\\exp(\\mathbf z_u^T\\mathbf z_n)}","parts":[{"sym":"\\sum_{u\\in V}","say":"모든 출발 노드 u"},{"sym":"N_R(u)","say":"u에서 출발한 워크에서 본 주변 노드"},{"sym":"P(v\\mid\\mathbf z_u)","say":"u와 v가 함께 나올 예측 확률, **소프트맥스(Softmax)**"},{"sym":"\\sum_{n\\in V}","say":"분모는 모든 노드를 돌아요, 비싼 부분"}],"whole":"워크에서 함께 나온 쌍의 확률을 높이게 배우는 게 **딥워크(DeepWalk)** 목적 함수예요"},{"kind":"steps","head":"직접 계산: 소프트맥스","given":"노드 3개, $\\mathbf z_u^T\\mathbf z_n$이 $v$에 2, 나머지 두 노드에 1과 0","steps":["1단계. 지수: $e^2=7.389$, $e^1=2.718$, $e^0=1$","2단계. 합 $11.107$","3단계. $P(v\\mid\\mathbf z_u)=7.389/11.107=0.665$","4단계. 나머지는 $0.245$, $0.090$","5단계. 이 쌍의 손실 $-\\log0.665=0.408$"],"answer":"분모에 노드 전부가 들어가 전체 비용이 $O(|V|^2)$로 커져요"},{"kind":"steps","head":"직접 계산: 문맥과 SGD","given":"워크 [s, 5, 8, 9, 8, 11], 윈도 크기 1","steps":["1단계. 가운데 9의 문맥은 앞뒤 {8, 8}","2단계. 가운데 5의 문맥은 {s, 8}","3단계. 이런 $(u,v)$ 쌍이 **스킵그램(Skip-gram)** 학습 예제예요","4단계. SGD: $\\mathbf z_v=(1,1)$, 기울기 $(0.5,-1)$, $\\eta=0.1$","5단계. $\\mathbf z_v\\leftarrow\\mathbf z_v-\\eta\\nabla=(1-0.05,\\ 1+0.1)$"],"answer":"$\\mathbf z_v=(0.95,\\ 1.1)$"},{"kind":"english","head":"시험 문장: DeepWalk","en":"DeepWalk runs fixed-length unbiased random walks and treats each walk as a sentence for skip-gram.","ko":"DeepWalk는 고정 길이의 편향 없는 랜덤워크를 돌리고 각 워크를 스킵그램의 문장으로 취급해요.","tip":"The main cost is the softmax term summing over all nodes."},{"kind":"english","head":"시험 문장: 왜 랜덤워크","en":"Random walks are expressive (local and multi-hop information) and efficient (only co-occurring pairs).","ko":"랜덤워크는 국소와 다중 홉 정보를 담아 표현력이 있고, 함께 나온 쌍만 봐서 효율적이에요."},{"kind":"check","q":"**Co-occurrence**는 DeepWalk에서 무엇을 뜻하나요?","choices":["두 노드가 같은 워크 문맥에 함께 나타남","두 노드의 차수가 같음","두 노드가 한 번도 안 만남"],"a":0,"why":"**동시 출현(Co-occurrence)** 빈도가 **랜덤워크(Random walk)** 기반 유사도예요"},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**딥워크(DeepWalk)**는 **편향 없는(Unbiased)** 워크, 편향을 주는 건 node2vec이에요","워크 개수 기호가 p.98은 $k$, p.106은 $r$이에요. 음성 샘플링의 $k$와 헷갈리지 마세요","비싼 곳은 **소프트맥스(Softmax)** 분모예요. 다음 단원에서 해결해요"]},{"kind":"recap","items":["**랜덤워크(Random walk)**: u에서 출발해 v를 자주 지나면 비슷","**딥워크(DeepWalk)** = **편향 없는(Unbiased)** 워크 + **스킵그램(Skip-gram)** + SGD","워크는 문장, 노드는 단어로 보는 **워드투벡(word2vec)** 빌리기","**동시 출현(Co-occurrence)**을 배우지만 **소프트맥스(Softmax)** 분모가 비싸요","오늘의 용어: Random walk(랜덤워크), DeepWalk(딥워크), word2vec(워드투벡), Skip-gram(스킵그램), Co-occurrence(동시 출현), Softmax(소프트맥스), Unbiased(편향 없는)"]}]},{"id":"w1-8","title":"산책에 손잡이 달기: node2vec","goal":"p와 q로 BFS, DFS 워크를 만들고 node2vec 전이 확률을 계산할 수 있어요","terms":[{"en":"node2vec","ko":"노드투벡","say":"p와 q로 걷는 방식을 조절하는 임베딩 모델"},{"en":"Biased random walk","ko":"편향 랜덤워크","say":"다음 걸음 확률에 차등을 준 워크"},{"en":"Return parameter","ko":"되돌아가기 파라미터","say":"직전 노드로 돌아가는 정도를 정하는 p"},{"en":"In-out parameter","ko":"들어가고 나가기 파라미터","say":"안쪽과 바깥쪽 이동을 정하는 q"},{"en":"BFS","ko":"너비 우선 탐색","say":"출발점 근처를 넓게 둘러봄"},{"en":"DFS","ko":"깊이 우선 탐색","say":"한 방향으로 멀리 나감"},{"en":"Structural equivalence","ko":"구조적 동치","say":"멀리 있어도 주변 모양, 역할이 같음"},{"en":"Homophily","ko":"동질성","say":"비슷한 것끼리, 같은 무리끼리 연결되는 경향"},{"en":"Negative sampling","ko":"음성 샘플링","say":"모든 노드 대신 k개만 뽑아 남남으로 비교"}],"slides":[{"kind":"title","big":"산책에 손잡이 달기","sub":"node2vec: p와 q로 조절하는 편향 랜덤워크"},{"kind":"goal","items":["**구조적 동치(Structural equivalence)**와 **동질성(Homophily)**을 구별할 수 있어요","**너비 우선 탐색(BFS)**과 **깊이 우선 탐색(DFS)** 워크를 p, q로 만들 수 있어요","**노드투벡(node2vec)** 전이 확률을 계산할 수 있어요","**음성 샘플링(Negative sampling)**이 왜 필요한지 말할 수 있어요"]},{"kind":"analogy","head":"비슷하다의 두 가지 뜻","scene":"두 팀의 팀장은 멀리 있어도 역할이 같아요. 같은 동아리 회원은 역할은 달라도 한 무리예요.","map":[["두 팀의 팀장","**구조적 동치(Structural equivalence)**"],["같은 동아리 회원","**동질성(Homophily)**"],["우리 동네를 넓게 둘러보기","**너비 우선 탐색(BFS)**"],["한 길로 멀리 원정 가기","**깊이 우선 탐색(DFS)**"]]},{"kind":"points","head":"앞 단원 다시 부르기","items":["**딥워크(DeepWalk)**는 이웃을 똑같은 확률로 고르는 **랜덤워크(Random walk)**였어요","학습은 **스킵그램(Skip-gram)**, 비싼 곳은 **소프트맥스(Softmax)** 분모","node2vec은 학습은 그대로, 걷는 법만 바꿔요","그리고 비싼 분모는 음성 샘플링으로 풀어요"]},{"kind":"compare","head":"BFS 같은 워크와 DFS 같은 워크","cols":["구분","**너비 우선 탐색(BFS)**","**깊이 우선 탐색(DFS)**"],"rows":[["시각","국소(local view)","전역(global view)"],["잘 잡는 것","**구조적 동치(Structural equivalence)**","**동질성(Homophily)**, 커뮤니티"],["설정","$p$를 낮게","$q$를 낮게"]]},{"kind":"figure","head":"직전 노드와의 거리로 점수 매기기","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><line class=\"e\" x1=\"70\" y1=\"150\" x2=\"220\" y2=\"50\"/><line class=\"e\" x1=\"220\" y1=\"150\" x2=\"220\" y2=\"50\"/><line class=\"e\" x1=\"220\" y1=\"150\" x2=\"380\" y2=\"90\"/><line class=\"e\" x1=\"220\" y1=\"150\" x2=\"380\" y2=\"220\"/><line class=\"e2\" x1=\"90\" y1=\"150\" x2=\"188\" y2=\"150\"/><polygon class=\"arrow\" points=\"200,150 188,156 188,144\"/><circle class=\"n3\" cx=\"70\" cy=\"150\" r=\"20\"/><text class=\"tl\" x=\"70\" y=\"156\" font-size=\"16\" text-anchor=\"middle\">t<\/text><circle class=\"n2\" cx=\"220\" cy=\"150\" r=\"20\"/><text class=\"tl\" x=\"220\" y=\"156\" font-size=\"16\" text-anchor=\"middle\">v<\/text><circle class=\"n\" cx=\"220\" cy=\"50\" r=\"20\"/><text class=\"tl\" x=\"220\" y=\"56\" font-size=\"16\" text-anchor=\"middle\">x1<\/text><circle class=\"n\" cx=\"380\" cy=\"90\" r=\"20\"/><text class=\"tl\" x=\"380\" y=\"96\" font-size=\"16\" text-anchor=\"middle\">x2<\/text><circle class=\"n\" cx=\"380\" cy=\"220\" r=\"20\"/><text class=\"tl\" x=\"380\" y=\"226\" font-size=\"16\" text-anchor=\"middle\">x3<\/text><text class=\"tb\" x=\"20\" y=\"30\" font-size=\"16\" text-anchor=\"start\">방금 t에서 v로 왔어요<\/text><text class=\"t b1\" x=\"145\" y=\"185\" font-size=\"16\" text-anchor=\"middle\">1/p (거리 0)<\/text><text class=\"t b2\" x=\"250\" y=\"45\" font-size=\"16\" text-anchor=\"start\">1 (거리 1)<\/text><text class=\"t b3\" x=\"410\" y=\"95\" font-size=\"16\" text-anchor=\"start\">1/q<\/text><text class=\"t b3\" x=\"410\" y=\"225\" font-size=\"16\" text-anchor=\"start\">1/q<\/text><text class=\"tm b3\" x=\"300\" y=\"262\" font-size=\"15\" text-anchor=\"middle\">x2, x3은 t에서 거리 2<\/text><\/svg>","caption":"**노드투벡(node2vec)**의 다음 걸음. 거리는 현재 노드 v가 아니라 직전 노드 t에서 재요","builds":3},{"kind":"formula","head":"비정규화 점수","tex":"\\alpha_{pq}(t,x)=\\begin{cases}1/p & d_{tx}=0\\\\ 1 & d_{tx}=1\\\\ 1/q & d_{tx}=2\\end{cases}","parts":[{"sym":"t","say":"직전 노드, 방금 떠나온 곳"},{"sym":"x","say":"현재 노드 v의 이웃 중 다음 후보"},{"sym":"d_{tx}","say":"직전 노드 t와 x의 최단 거리"},{"sym":"p","say":"**되돌아가기 파라미터(Return parameter)**"},{"sym":"q","say":"**들어가고 나가기 파라미터(In-out parameter)**"}],"whole":"직전 노드와의 거리 0, 1, 2에 따라 점수 $1/p$, $1$, $1/q$를 줘요"},{"kind":"formula","head":"확률로 바꾸기","tex":"P(x\\mid v,t)=\\frac{\\alpha_{pq}(t,x)}{\\sum_{x'\\in N(v)}\\alpha_{pq}(t,x')}","parts":[{"sym":"\\alpha_{pq}(t,x)","say":"비정규화 점수"},{"sym":"\\sum_{x'\\in N(v)}","say":"v의 모든 이웃 점수의 합"},{"sym":"P(x\\mid v,t)","say":"진짜 확률, 합이 1"}],"whole":"점수를 합으로 나누면 **편향 랜덤워크(Biased random walk)**의 다음 걸음 확률이에요"},{"kind":"points","head":"손잡이 p, q 돌리기","items":["$p$는 **되돌아가기 파라미터(Return parameter)**, 작게 하면 동네를 맴돌아요","$q$는 **들어가고 나가기 파라미터(In-out parameter)**, 작게 하면 멀리 나가요","$p$ 작게는 **너비 우선 탐색(BFS)** 같고, $q$ 작게는 **깊이 우선 탐색(DFS)** 같아요","$p=q=1$이면 모두 1이라 딥워크와 같은 편향 없는 워크","어느 쪽이 좋은지는 그래프와 과제에 따라 달라요"]},{"kind":"steps","head":"직접 계산: 2025 가을 중간 1번형","given":"$p=2$, $q=1$. 워커가 A에서 B로 왔고 B의 이웃은 {A, C}","steps":["1단계. 직전 노드는 A. $d(A,A)=0$, $d(A,C)=2$","2단계. 비정규화: A는 $1/p=1/2$, C는 $1/q=1$","3단계. 합 $1.5$","4단계. $P(A)=0.5/1.5=1/3$, $P(C)=1/1.5=2/3$"],"answer":"A $1/3$, C $2/3$. $p$가 커서 되돌아가기가 억제돼요"},{"kind":"steps","head":"직접 계산: 2023 가을 중간 2번 설정","given":"$p=0.2$, $q=0.6$, $t\\to v$. 이웃 $t$(거리 0), $x_1$(거리 1), $x_2, x_3$(거리 2)","steps":["1단계. 비정규화: $1/0.2=5$, $1$, $1/0.6=1.667$, $1.667$","2단계. 합 $9.333$","3단계. $t$: $5/9.333=0.536$","4단계. $x_1$: $0.107$, $x_2$와 $x_3$: 각 $0.179$"],"answer":"되돌아가기가 가장 커서 **너비 우선 탐색(BFS)** 같은 워크예요"},{"kind":"formula","head":"음성 샘플링","tex":"\\log\\frac{\\exp(\\mathbf z_u^T\\mathbf z_v)}{\\sum_{n\\in V}\\exp(\\mathbf z_u^T\\mathbf z_n)}\\approx\\log\\sigma(\\mathbf z_u^T\\mathbf z_v)-\\sum_{i=1}^{k}\\log\\sigma(\\mathbf z_u^T\\mathbf z_{n_i})","parts":[{"sym":"\\sigma","say":"시그모이드, 0에서 1 사이로 눌러요"},{"sym":"n_i\\sim P_V","say":"차수에 비례해 뽑은 음성 노드"},{"sym":"k","say":"음성 노드 수, 실제로 5에서 20, 크면 안정적"},{"sym":"\\sum_{n\\in V}","say":"없애고 싶은 비싼 소프트맥스 분모"}],"whole":"모든 노드 대신 $k$개만 남남으로 비교하는 게 **음성 샘플링(Negative sampling)**이에요"},{"kind":"english","head":"시험 문장: BFS","en":"BFS explores the local neighborhood near the starting node, so it is good at capturing structural equivalence.","ko":"BFS는 출발 노드 가까운 국소 이웃을 탐색하므로 구조적 동치를 잘 포착해요."},{"kind":"english","head":"시험 문장: DFS","en":"DFS moves farther away from the starting node, so it captures communities, that is, homophily.","ko":"DFS는 출발 노드에서 멀리 가므로 커뮤니티, 즉 동질성을 잘 포착해요."},{"kind":"english","head":"시험 문장: 전이 확률","en":"In node2vec, the unnormalized probability is $1/p$ to return, $1$ at distance 1, and $1/q$ at distance 2.","ko":"node2vec의 비정규화 전이 확률은 되돌아가면 $1/p$, 거리 1이면 $1$, 거리 2이면 $1/q$예요.","tip":"마지막에 붙이기: then they are normalized to sum to one."},{"kind":"check","q":"**Homophily**의 뜻은?","choices":["멀리 있어도 역할이 같음","비슷한 것끼리, 같은 무리끼리 연결되는 경향","직전 노드로 되돌아가는 확률","음성 노드를 뽑는 방법"],"a":1,"why":"**동질성(Homophily)**은 같은 커뮤니티끼리 이어지는 성질이고 **깊이 우선 탐색(DFS)** 워크가 잘 잡아요"},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["거리는 현재 노드 $v$가 아니라 직전 노드 $t$에서 재요. 가장 흔한 실수예요","비정규화 값만 묻는지, 정규화 확률까지 묻는지 확인해요","BFS는 $p$ 낮게, DFS는 $q$ 낮게(L1 p.105)"]},{"kind":"recap","items":["**노드투벡(node2vec)** = 딥워크 학습 + **편향 랜덤워크(Biased random walk)**","**되돌아가기 파라미터(Return parameter)** $p$, **들어가고 나가기 파라미터(In-out parameter)** $q$로 $1/p$, $1$, $1/q$","**너비 우선 탐색(BFS)**은 **구조적 동치(Structural equivalence)**, **깊이 우선 탐색(DFS)**은 **동질성(Homophily)**","**음성 샘플링(Negative sampling)**으로 비싼 분모를 없애요","오늘의 용어: node2vec(노드투벡), Biased random walk(편향 랜덤워크), Return parameter(되돌아가기 파라미터), In-out parameter(들어가고 나가기 파라미터), BFS(너비 우선 탐색), DFS(깊이 우선 탐색), Structural equivalence(구조적 동치), Homophily(동질성), Negative sampling(음성 샘플링)"]}]},{"id":"w1-9","title":"직접 친구와 친구 목록: LINE","goal":"1차와 2차 근접성을 구별하고 LINE의 p1, p2 확률을 계산할 수 있어요","terms":[{"en":"LINE","ko":"라인","say":"1차와 2차 근접성을 보존하는 임베딩 모델"},{"en":"First-order proximity","ko":"1차 근접성","say":"직접 연결의 세기, 엣지 가중치"},{"en":"Second-order proximity","ko":"2차 근접성","say":"공통 이웃이 얼마나 겹치는지"},{"en":"Context vector","ko":"문맥 벡터","say":"남의 이웃 역할일 때 쓰는 두 번째 벡터 u'"},{"en":"Edge sampling","ko":"엣지 샘플링","say":"가중치에 비례해 엣지를 뽑고 가중치 1로 취급"},{"en":"Concatenate","ko":"이어 붙이기","say":"두 벡터를 옆으로 붙여 하나로 만듦"}],"slides":[{"kind":"title","big":"직접 친구와 친구 목록","sub":"LINE: 1차 근접성과 2차 근접성"},{"kind":"goal","items":["**1차 근접성(First-order proximity)**과 **2차 근접성(Second-order proximity)**을 구별할 수 있어요","**라인(LINE)**의 $p_1$, $p_2$ 확률을 계산할 수 있어요","**엣지 샘플링(Edge sampling)**이 왜 필요한지 말할 수 있어요"]},{"kind":"analogy","head":"단짝과 취향이 같은 친구","scene":"매일 붙어 다니는 단짝은 직접 가까워요. 서로 모르지만 친구 목록이 똑같은 두 사람도 비슷한 사람이죠.","map":[["단짝, 직접 연결","**1차 근접성(First-order proximity)**"],["친구 목록이 겹침","**2차 근접성(Second-order proximity)**"],["함께 다닌 횟수","엣지 가중치 $w_{ij}$"],["두 관점 점수를 합친 명함","두 벡터 **이어 붙이기(Concatenate)**"]]},{"kind":"points","head":"앞 단원과 비교","items":["**노드투벡(node2vec)**은 **랜덤워크(Random walk)**로 문맥을 만들었어요","LINE은 워크 대신 엣지를 직접 뽑아 학습해요","**음성 샘플링(Negative sampling)**과 SGD 반복은 같아요","차이: 무엇을 보존할지 근접성으로 명시했어요","GNN 2025 가을 중간 2번에 $p_2$ 계산이 나왔어요"]},{"kind":"figure","head":"직접 연결과 공통 이웃","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 280\"><line class=\"e\" x1=\"50\" y1=\"40\" x2=\"175\" y2=\"70\"/><line class=\"e\" x1=\"50\" y1=\"40\" x2=\"175\" y2=\"190\"/><line class=\"e\" x1=\"50\" y1=\"100\" x2=\"175\" y2=\"70\"/><line class=\"e\" x1=\"50\" y1=\"100\" x2=\"175\" y2=\"190\"/><line class=\"e\" x1=\"50\" y1=\"160\" x2=\"175\" y2=\"70\"/><line class=\"e\" x1=\"50\" y1=\"160\" x2=\"175\" y2=\"190\"/><line class=\"e\" x1=\"50\" y1=\"220\" x2=\"175\" y2=\"70\"/><line class=\"e\" x1=\"50\" y1=\"220\" x2=\"175\" y2=\"190\"/><line class=\"e\" x1=\"175\" y1=\"190\" x2=\"290\" y2=\"190\"/><line class=\"e2 b2\" x1=\"175\" y1=\"190\" x2=\"290\" y2=\"190\"/><circle class=\"n3\" cx=\"50\" cy=\"40\" r=\"16\"/><text class=\"tl\" x=\"50\" y=\"46\" font-size=\"16\" text-anchor=\"middle\">1<\/text><circle class=\"n3\" cx=\"50\" cy=\"100\" r=\"16\"/><text class=\"tl\" x=\"50\" y=\"106\" font-size=\"16\" text-anchor=\"middle\">2<\/text><circle class=\"n3\" cx=\"50\" cy=\"160\" r=\"16\"/><text class=\"tl\" x=\"50\" y=\"166\" font-size=\"16\" text-anchor=\"middle\">3<\/text><circle class=\"n3\" cx=\"50\" cy=\"220\" r=\"16\"/><text class=\"tl\" x=\"50\" y=\"226\" font-size=\"16\" text-anchor=\"middle\">4<\/text><circle class=\"n\" cx=\"175\" cy=\"70\" r=\"20\"/><text class=\"tl\" x=\"175\" y=\"76\" font-size=\"16\" text-anchor=\"middle\">5<\/text><circle class=\"n\" cx=\"175\" cy=\"190\" r=\"20\"/><text class=\"tl\" x=\"175\" y=\"196\" font-size=\"16\" text-anchor=\"middle\">6<\/text><circle class=\"n\" cx=\"290\" cy=\"190\" r=\"20\"/><text class=\"tl\" x=\"290\" y=\"196\" font-size=\"16\" text-anchor=\"middle\">7<\/text><circle class=\"n2 b1\" cx=\"175\" cy=\"70\" r=\"20\"/><text class=\"tl b1\" x=\"175\" y=\"76\" font-size=\"16\" text-anchor=\"middle\">5<\/text><circle class=\"n2 b1\" cx=\"175\" cy=\"190\" r=\"20\"/><text class=\"tl b1\" x=\"175\" y=\"196\" font-size=\"16\" text-anchor=\"middle\">6<\/text><text class=\"tb b1\" x=\"320\" y=\"50\" font-size=\"16\" text-anchor=\"start\">5와 6: 2차 근접성<\/text><text class=\"t b1\" x=\"320\" y=\"75\" font-size=\"15\" text-anchor=\"start\">공통 이웃 1, 2, 3, 4<\/text><text class=\"tb b2\" x=\"320\" y=\"130\" font-size=\"16\" text-anchor=\"start\">6과 7: 1차 근접성<\/text><text class=\"t b2\" x=\"320\" y=\"155\" font-size=\"15\" text-anchor=\"start\">굵은 엣지 w = 5<\/text><text class=\"tb b3\" x=\"240\" y=\"262\" font-size=\"16\" text-anchor=\"middle\">최종 벡터 = [1차 벡터, 2차 벡터] 이어 붙이기<\/text><\/svg>","caption":"L1 p.113-116 예시를 줄였어요. **라인(LINE)**은 두 근접성을 따로 배워 이어 붙여요","builds":3},{"kind":"formula","head":"1차 근접성","tex":"p_1(v_i,v_j)=\\frac{1}{1+\\exp(-\\vec u_i^{\\,T}\\vec u_j)},\\quad \\hat p_1(v_i,v_j)=\\frac{w_{ij}}{\\sum_{(i',j')}w_{i'j'}}","parts":[{"sym":"\\vec u_i","say":"노드 i의 벡터, 노드당 1벌"},{"sym":"p_1","say":"내적의 시그모이드, 모델이 본 연결 확률"},{"sym":"\\hat p_1","say":"실제 가중치 비율, 경험 분포"},{"sym":"O_1\\propto-\\sum w_{ij}\\log p_1","say":"둘을 닮게 하는 목적(KL 발산)"}],"whole":"**1차 근접성(First-order proximity)**은 내적 시그모이드를 실제 가중치 비율에 맞춰요"},{"kind":"formula","head":"2차 근접성","tex":"p_2(v_j\\mid v_i)=\\frac{\\exp(\\vec u_j'^{\\,T}\\vec u_i)}{\\sum_{k=1}^{|V|}\\exp(\\vec u_k'^{\\,T}\\vec u_i)},\\quad \\hat p_2(v_j\\mid v_i)=\\frac{w_{ij}}{\\sum_{k}w_{ik}}","parts":[{"sym":"\\vec u_i","say":"기준 노드의 출발(source) 벡터"},{"sym":"\\vec u_j'","say":"후보의 **문맥 벡터(Context vector)**"},{"sym":"\\sum_{k=1}^{|V|}","say":"모든 노드, 기준 노드 자신도 포함"},{"sym":"\\hat p_2","say":"노드 i의 엣지 가중치 비율"}],"whole":"**2차 근접성(Second-order proximity)**은 이웃을 부르는 확률 분포를 실제 비율에 맞춰요"},{"kind":"steps","head":"직접 계산: 2025 가을 중간 2번","given":"$w_{AB}=2$, $w_{BC}=1$, $w_{CD}=3$, $u_B=0.5$, 문맥 $u'_A=0.5$, $u'_B=1$, $u'_C=-1$, $u'_D=-0.5$","steps":["1단계. $u_B$와 문맥 벡터 곱: A $0.25$, B $0.5$, C $-0.5$, D $-0.25$","2단계. 지수: $1.28$, $1.65$, $0.61$, $0.78$, 합 $4.32$","3단계. $p_2(A\\mid B)=1.28/4.32=0.296$","4단계. $p_2(B\\mid B)=0.382$, $p_2(C\\mid B)=0.141$, $p_2(D\\mid B)=0.181$","5단계. 실제 비율: $\\hat p_2(A\\mid B)=2/3$, $\\hat p_2(C\\mid B)=1/3$"],"answer":"학습은 $p_2$를 $\\hat p_2$ 쪽으로 옮겨요"},{"kind":"steps","head":"직접 계산: 1차 근접성","given":"같은 문제의 $u_A=1$, $u_B=0.5$","steps":["1단계. 내적 $u_A u_B=1\\times0.5=0.5$","2단계. $e^{-0.5}=0.61$","3단계. $p_1(A,B)=1/(1+0.61)$"],"answer":"$p_1(A,B)=0.621$"},{"kind":"compare","head":"1차와 2차 근접성","cols":["구분","**1차 근접성(First-order proximity)**","**2차 근접성(Second-order proximity)**"],"rows":[["뜻","직접 연결의 세기","공통 이웃 분포의 유사성"],["모델 확률","$p_1$: 시그모이드","$p_2$: 소프트맥스"],["경험 분포","$w_{ij}/\\sum w$, 전체 엣지","$w_{ij}/\\sum_k w_{ik}$, 노드 i의 엣지"],["벡터","노드당 1벌","노드당 2벌, $u$와 $u'$"]]},{"kind":"points","head":"왜 엣지 샘플링일까","items":["기울기에 엣지 가중치 $w_{ij}$가 그대로 곱해져요","가중치 1과 1000이 섞이면 학습률을 맞출 수 없어요","**엣지 샘플링(Edge sampling)**: 가중치에 비례해 자주 뽑고 가중치 1로 취급","복잡도 $\\Theta(dK|E|)$, 엣지 수에 선형이에요"]},{"kind":"english","head":"시험 문장: 1차 근접성","en":"First-order proximity is the pairwise proximity between directly connected nodes, given by the edge weight $w_{ij}$.","ko":"1차 근접성은 직접 연결된 두 노드 사이 근접성으로, 엣지 가중치 $w_{ij}$이고 엣지가 없으면 0이에요."},{"kind":"english","head":"시험 문장: 2차 근접성","en":"Two nodes have high second-order proximity if they share many common neighbors.","ko":"공통 이웃을 많이 공유하는 두 노드는 2차 근접성이 높아요."},{"kind":"english","head":"시험 문장: LINE","en":"LINE trains first- and second-order embeddings separately, concatenates them, and uses edge sampling.","ko":"LINE은 1차와 2차 임베딩을 따로 학습해 이어 붙이고, 엣지 샘플링을 써요.","tip":"edge sampling의 이유: to keep gradients stable"},{"kind":"check","q":"**Second-order proximity**가 높은 두 노드는?","choices":["직접 엣지 가중치가 큰 두 노드","공통 이웃을 많이 공유하는 두 노드","차수가 가장 큰 두 노드"],"a":1,"why":"p.113의 노드 5와 6은 직접 연결은 없지만 이웃 1, 2, 3, 4를 공유해 **2차 근접성(Second-order proximity)**이 높아요"},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["$p_2$는 기준 노드의 출발 벡터 $u_i$와 후보의 **문맥 벡터(Context vector)** $u'_j$를 곱해요","분모는 모든 노드라 $p_2(B\\mid B)$처럼 자기 자신도 들어가요","슬라이드는 $p_2$를 joint probability라 했지만 실제로는 조건부 확률이에요"]},{"kind":"recap","items":["**라인(LINE)**은 1차와 2차 근접성을 따로 배워 **이어 붙이기(Concatenate)**","**1차 근접성(First-order proximity)**: 직접 연결, 시그모이드","**2차 근접성(Second-order proximity)**: 공통 이웃, 소프트맥스와 **문맥 벡터(Context vector)**","**엣지 샘플링(Edge sampling)**으로 기울기를 안정시켜요","오늘의 용어: LINE(라인), First-order proximity(1차 근접성), Second-order proximity(2차 근접성), Context vector(문맥 벡터), Edge sampling(엣지 샘플링), Concatenate(이어 붙이기)"]}]},{"id":"w1-10","title":"얕은 임베딩의 끝과 한계: struc2vec, subgraph2vec, metapath2vec","goal":"역할, 부분 그래프, 이종 그래프용 임베딩을 구별하고, 전이적 한계 때문에 GNN이 필요한 이유를 말할 수 있어요","terms":[{"en":"struc2vec","ko":"스트럭투벡","say":"멀리 있어도 역할이 같은 노드를 가깝게 임베딩"},{"en":"Structural identity","ko":"구조적 정체성","say":"네트워크 구조만으로 본 노드의 역할"},{"en":"subgraph2vec","ko":"서브그래프투벡","say":"WL로 이름 붙인 루트 부분 그래프를 벡터로"},{"en":"Heterogeneous graph","ko":"이종 그래프","say":"노드와 관계 종류가 여러 개인 그래프"},{"en":"Meta path","ko":"메타패스","say":"저자-논문-학회처럼 정해 둔 타입 순서"},{"en":"metapath2vec","ko":"메타패스투벡","say":"메타패스를 따라 걷고 스킵그램으로 학습"},{"en":"Transductive","ko":"전이적","say":"학습 때 본 노드에만 임베딩이 있음"},{"en":"Inductive","ko":"귀납적","say":"처음 보는 노드와 그래프에도 일반화됨"}],"slides":[{"kind":"title","big":"얕은 임베딩의 끝과 한계","sub":"struc2vec, subgraph2vec, metapath2vec, 그리고 전이적 한계"},{"kind":"goal","items":["**스트럭투벡(struc2vec)**이 **구조적 정체성(Structural identity)**을 잡는 법을 말할 수 있어요","**이종 그래프(Heterogeneous graph)**에서 **메타패스(Meta path)** 워크를 계산할 수 있어요","얕은 임베딩이 **전이적(Transductive)**이라 GNN이 필요한 이유를 설명할 수 있어요"]},{"kind":"analogy","head":"서울 팀장과 부산 팀장","scene":"두 지점 팀장은 한 번도 만난 적이 없어요. 그래도 부하 직원 수와 보고 구조가 같으면 역할이 같은 사람이죠.","map":[["두 지점의 팀장","**구조적 정체성(Structural identity)**이 같은 노드"],["만난 적 없음","홉 거리가 멀다"],["직원 수, 그 직원들의 직원 수 비교","차수 수열 비교"]]},{"kind":"points","head":"struc2vec 4단계","items":["앞에서 본 **노드투벡(node2vec)**은 가까이 있으면 비슷하다고 봐서 먼 역할을 놓쳤어요","1. 나, 이웃, 이웃의 이웃 차수 수열을 비교해 거리 $f_k$를 쌓아요","2. 깊이 $k$마다 층을 만든 다층 그래프, $w_k(u,v)=\\exp\\{-f_k(u,v)\\}$","3. 확률 $p$로 층 안, $1-p$로 층 이동하는 편향 워크","4. **스킵그램(Skip-gram)**(계층적 소프트맥스)으로 학습"]},{"kind":"steps","head":"직접 계산: struc2vec 거리","given":"L1 p.121, 두 노드의 자기 차수 4와 3","steps":["1단계. $k=0$: 정렬 비용 $\\max/\\min-1=4/3-1=0.33$, $f_0=0.33$","2단계. $k=1$: $g=3.33$이라 $f_1=0.33+3.33=3.66$","3단계. $k=2$: $g=1$이라 $f_2=4.66$","4단계. 층별 가중치 $w_0=e^{-0.33}=0.72$","5단계. $w_1=e^{-3.66}=0.026$, $w_2=e^{-4.66}=0.0095$"],"answer":"깊이 볼수록 차이가 드러나 **스트럭투벡(struc2vec)** 유사도가 떨어져요"},{"kind":"points","head":"subgraph2vec","items":["**서브그래프투벡(subgraph2vec)**은 노드 주변 덩어리, 루트 부분 그래프를 벡터로 만들어요","덩어리 이름표는 앞에서 본 **색 정제(Color refinement)**, WL 재레이블링으로 붙여요","문맥은 이웃의 차수 $d-1$, $d$, $d+1$ 부분 그래프(방사형 문맥)","수정한 스킵그램으로 학습해요"]},{"kind":"points","head":"이종 그래프와 메타패스","items":["저자, 논문, 학회처럼 종류가 여럿이면 **이종 그래프(Heterogeneous graph)**","$G=(V,E,R,T)$: 노드 타입 $T$, 관계 타입 $R$","아무렇게나 걸으면 의미가 흐려져요","**메타패스(Meta path)**: 저자-논문-학회-논문-저자 같은 타입 순서","APA(공저자)와 APCPA(같은 학회)는 의미가 달라요"]},{"kind":"figure","head":"메타패스를 따라 한 걸음","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 275\"><line class=\"e\" x1=\"240\" y1=\"150\" x2=\"150\" y2=\"60\"/><line class=\"e\" x1=\"240\" y1=\"150\" x2=\"330\" y2=\"60\"/><line class=\"e\" x1=\"240\" y1=\"150\" x2=\"400\" y2=\"150\"/><line class=\"e\" x1=\"240\" y1=\"150\" x2=\"170\" y2=\"240\"/><line class=\"e\" x1=\"240\" y1=\"150\" x2=\"310\" y2=\"240\"/><line class=\"e2\" x1=\"102\" y1=\"150\" x2=\"208\" y2=\"150\"/><polygon class=\"arrow\" points=\"220,150 208,156 208,144\"/><line class=\"e2 b2\" x1=\"240\" y1=\"150\" x2=\"170\" y2=\"240\"/><line class=\"e2 b2\" x1=\"240\" y1=\"150\" x2=\"310\" y2=\"240\"/><circle class=\"n2\" cx=\"240\" cy=\"150\" r=\"22\"/><text class=\"tl\" x=\"240\" y=\"156\" font-size=\"14\" text-anchor=\"middle\">a4<\/text><circle class=\"n\" cx=\"80\" cy=\"150\" r=\"22\"/><text class=\"tl\" x=\"80\" y=\"156\" font-size=\"14\" text-anchor=\"middle\">CMU<\/text><circle class=\"n\" cx=\"150\" cy=\"60\" r=\"22\"/><text class=\"tl\" x=\"150\" y=\"66\" font-size=\"14\" text-anchor=\"middle\">a2<\/text><circle class=\"n\" cx=\"330\" cy=\"60\" r=\"22\"/><text class=\"tl\" x=\"330\" y=\"66\" font-size=\"14\" text-anchor=\"middle\">a3<\/text><circle class=\"n\" cx=\"400\" cy=\"150\" r=\"22\"/><text class=\"tl\" x=\"400\" y=\"156\" font-size=\"14\" text-anchor=\"middle\">a5<\/text><circle class=\"n3\" cx=\"170\" cy=\"240\" r=\"22\"/><text class=\"tl\" x=\"170\" y=\"246\" font-size=\"14\" text-anchor=\"middle\">p2<\/text><circle class=\"n3\" cx=\"310\" cy=\"240\" r=\"22\"/><text class=\"tl\" x=\"310\" y=\"246\" font-size=\"14\" text-anchor=\"middle\">p3<\/text><text class=\"tb b1\" x=\"240\" y=\"24\" font-size=\"15\" text-anchor=\"middle\">순서 O-A-P-V-P-A-O, O에서 A로 왔어요<\/text><text class=\"tb b2\" x=\"168\" y=\"205\" font-size=\"15\" text-anchor=\"middle\">1/2<\/text><text class=\"tb b2\" x=\"312\" y=\"205\" font-size=\"15\" text-anchor=\"middle\">1/2<\/text><text class=\"tm b3\" x=\"178\" y=\"115\" font-size=\"16\" text-anchor=\"middle\">0<\/text><text class=\"tm b3\" x=\"302\" y=\"115\" font-size=\"16\" text-anchor=\"middle\">0<\/text><text class=\"tm b3\" x=\"330\" y=\"140\" font-size=\"16\" text-anchor=\"middle\">0<\/text><\/svg>","caption":"L1 p.150. a4(저자) 다음은 논문(P) 타입만 갈 수 있어서 p2, p3이 각 1/2이에요","builds":3},{"kind":"formula","head":"metapath2vec 전이 확률","tex":"p(v^{i+1}\\mid v_t^i,\\mathcal P)=\\frac{1}{|N_{t+1}(v_t^i)|}","parts":[{"sym":"v_t^i","say":"i번째 걸음, 타입 t인 현재 노드"},{"sym":"N_{t+1}(v_t^i)","say":"이웃 중 **메타패스(Meta path)** 다음 타입 $t+1$인 노드들"},{"sym":"\\frac{1}{|N_{t+1}|}","say":"그중에서 똑같은 확률, 나머지 타입은 0"},{"sym":"\\sum_{u_t\\in V_t}","say":"++ 버전 소프트맥스 분모, 같은 타입만"}],"whole":"다음 타입 이웃 중에서만 균등하게 고르는 게 **메타패스투벡(metapath2vec)** 워크예요"},{"kind":"steps","head":"직접 계산: PathSim","given":"저자-학회-저자 메타패스(p.146). Mike: SIGMOD 2, VLDB 1. Jim: SIGMOD 50, VLDB 20","steps":["1단계. 둘 사이 경로 수 $2\\cdot50+1\\cdot20=120$","2단계. Mike 자기 왕복 $2\\cdot2+1\\cdot1=5$","3단계. Jim 자기 왕복 $50\\cdot50+20\\cdot20=2900$","4단계. $s=2\\cdot120/(5+2900)=240/2905=0.0826$"],"answer":"PathSim $0.0826$. 경로 수 120만 쓰면 유명 저자가 과대평가돼요"},{"kind":"figure","head":"새 노드가 오면?","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text class=\"tb b1\" x=\"125\" y=\"28\" font-size=\"16\" text-anchor=\"middle\">전이적(Transductive)<\/text><rect class=\"box b1\" x=\"20\" y=\"40\" width=\"210\" height=\"70\" rx=\"10\"/><text class=\"t b1\" x=\"125\" y=\"70\" font-size=\"16\" text-anchor=\"middle\">조회표 Z: 노드마다 열<\/text><text class=\"t b1\" x=\"125\" y=\"95\" font-size=\"15\" text-anchor=\"middle\">새 노드는 열이 없음<\/text><circle class=\"n4 b1\" cx=\"125\" cy=\"175\" r=\"20\"/><text class=\"tl b1\" x=\"125\" y=\"181\" font-size=\"16\" text-anchor=\"middle\">?<\/text><text class=\"tm b1\" x=\"125\" y=\"235\" font-size=\"16\" text-anchor=\"middle\">처음부터 다시 학습<\/text><text class=\"tb b2\" x=\"355\" y=\"28\" font-size=\"16\" text-anchor=\"middle\">귀납적(Inductive)<\/text><rect class=\"box2 b2\" x=\"250\" y=\"40\" width=\"210\" height=\"70\" rx=\"10\"/><text class=\"t b2\" x=\"355\" y=\"70\" font-size=\"16\" text-anchor=\"middle\">공유 함수 f(특징, 이웃)<\/text><text class=\"t b2\" x=\"355\" y=\"95\" font-size=\"15\" text-anchor=\"middle\">새 노드도 같은 f로<\/text><line class=\"e2 b2\" x1=\"355\" y1=\"155\" x2=\"355\" y2=\"122\"/><polygon class=\"arrow b2\" points=\"355,110 361,122 349,122\"/><circle class=\"n3 b2\" cx=\"355\" cy=\"175\" r=\"20\"/><text class=\"tl b2\" x=\"355\" y=\"181\" font-size=\"16\" text-anchor=\"middle\">N<\/text><text class=\"tm b2\" x=\"355\" y=\"235\" font-size=\"16\" text-anchor=\"middle\">바로 임베딩 생성<\/text><\/svg>","caption":"얕은 임베딩은 노드별 열을 외워 새 노드에 못 쓰고, GNN 방향의 함수는 새 노드도 계산해요","builds":2},{"kind":"points","head":"교수님이 꼭 짚은 한계","items":["얕은 임베딩은 성능이 나쁘지 않은데도 요즘 거의 안 써요","**조회표(Lookup table)** 기반이라 본질적으로 **전이적(Transductive)**이에요","새 노드, 새 그래프가 오면 처음부터 다시 학습해야 해요","파라미터 $O(|V|)$, 노드 사이 공유 없음, 노드 특징도 안 써요","그래서 **귀납적(Inductive)** 학습이 되는 깊은 인코더, GNN으로 가요"]},{"kind":"compare","head":"얕은 모델 한눈에","cols":["모델","비슷함의 정의","문맥 만들기"],"rows":[["DeepWalk","워크 동시 출현","편향 없는 워크"],["node2vec","BFS와 DFS 절충","$p,q$ 편향 워크"],["LINE","1차, 2차 근접성","엣지 샘플링"],["struc2vec","구조적 정체성(역할)","다층 그래프 워크"],["subgraph2vec","부분 그래프 이웃 공유","WL 루트 부분 그래프"],["metapath2vec","메타패스 의미","메타패스 워크"]]},{"kind":"english","head":"시험 문장: 얕은 인코더의 한계","en":"Shallow encoders need $O(|V|)$ parameters, ignore node features, and are inherently transductive.","ko":"얕은 인코더는 $O(|V|)$ 파라미터가 필요하고 노드 특징을 안 쓰며 본질적으로 전이적이에요.","tip":"이어서: so they cannot embed nodes unseen during training. Inductive learning motivates GNNs."},{"kind":"english","head":"시험 문장: metapath2vec","en":"metapath2vec walks along a predefined meta path; metapath2vec++ uses a type-specific softmax.","ko":"metapath2vec은 미리 정한 메타패스를 따라 걷고, metapath2vec++는 같은 타입끼리만 소프트맥스를 해요."},{"kind":"check","q":"**Transductive**의 뜻으로 맞는 것은?","choices":["학습 때 본 노드에만 임베딩이 있어 새 노드엔 못 쓴다","처음 보는 그래프에도 바로 쓸 수 있다","전이 학습(transfer learning)과 같은 말이다"],"a":0,"why":"**전이적(Transductive)**은 조회표의 한계예요. 새 노드에도 쓰는 건 **귀납적(Inductive)**"},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**전이적(Transductive)**은 전이 학습(transfer learning)과 전혀 다른 말이에요","GNN이면 자동으로 **귀납적(Inductive)**? 아니에요. 교수님: 설계에 따라 달라서 따로 한 주 다뤄요","struc2vec의 $p$는 층에 머물 확률로, node2vec의 $p$와 뜻이 달라요"]},{"kind":"recap","items":["**스트럭투벡(struc2vec)**: 멀리 있어도 **구조적 정체성(Structural identity)**이 같으면 가깝게","**서브그래프투벡(subgraph2vec)**: WL 이름표로 부분 그래프 임베딩","**메타패스투벡(metapath2vec)**: **이종 그래프(Heterogeneous graph)**에서 **메타패스(Meta path)** 따라 걷기","얕은 임베딩은 **전이적(Transductive)**, GNN은 **귀납적(Inductive)** 학습을 향해요","오늘의 용어: struc2vec(스트럭투벡), Structural identity(구조적 정체성), subgraph2vec(서브그래프투벡), Heterogeneous graph(이종 그래프), Meta path(메타패스), metapath2vec(메타패스투벡), Transductive(전이적), Inductive(귀납적)"]}]}]};
